function djST(s) { return String(s == null ? '' : s).replace(/\/+$/, '') }
function djHost(u) { var s = djST(u).replace(/^https?:\/\//, ''); var i = s.indexOf('/'); return i > 0 ? s.substring(0, i) : s }
function djGet(u, ms) { try { return String(java.ajax(djST(u) + '/', ms || 6000) || '') } catch (e) { return '' } }
function djB64(s) { try { return String(java.base64Decode(String(s)) || '') } catch (e) { return '' } }
function djGV(k, d) { var v = ''; try { v = String(source.get(k) || '') } catch (e) { } if (!v || v == 'null' || v == 'undefined') v = d || ''; return v }
function djSV(k, v) { try { source.put(k, String(v)) } catch (e) { } }
function djT(t) { try { java.longToast(t) } catch (e) { } }
function djNL() { return String.fromCharCode(10) }

function djPub() {
  var v = '';
  try { v = String(result['发布页地址'] || '') } catch (e) { }
  if (!v) v = djGV('dj_pub', '');
  if (!v) v = 'https://51dj31.com';
  return djST(v);
}

function djFetch() {
  var h = djGet(djPub(), 6000);
  if (h.length < 3000) {
    var m = h.match(/href\s*=\s*["'](https?:\/\/[^"']+)["']/i);
    if (m) { var h2 = djGet(m[1], 6000); if (h2) h = h2 }
  }
  if (!h) return '';
  var b = h.match(/Base64\.decode\(\s*["']([A-Za-z0-9\+\/=]{40,})["']\s*\)/);
  if (b) { var d = djB64(b[1]); if (d && d.length > 500) h = h + djNL() + d }
  return h;
}

function djSuffix(h) {
  var o = [], s = {}, m;
  var re = /['"]\.([a-z0-9][a-z0-9-]{2,}\.(?:cc|com|net|xyz|top|vip|site|club|live|app))['"]/gi;
  while ((m = re.exec(String(h))) != null) {
    var x = m[1].toLowerCase();
    if (s[x]) continue;
    if (x.indexOf('51') > -1 || x.indexOf('hub') > -1 || x.indexOf('shipin') > -1 || x.indexOf('gmail') > -1) continue;
    s[x] = 1; o.push(x);
  }
  return o;
}

var DJ_N = 2;
var DJ_W = ['carrier', 'adult', 'belong', 'against', 'buyer', 'beach', 'cabin', 'camera', 'cancer', 'cap', 'carbon', 'card'];

function djBuild() {
  var suf = djSuffix(djFetch());
  var cached = !suf.length;
  if (cached) suf = ['henoceapn.cc', 'siaefmykb.cc'];
  var n = Math.max(1, Math.min(6, parseInt(DJ_N, 10) || 4));
  var main = suf[1] ? Math.ceil(n / 2) : n;
  var ls = [], i;
  for (i = 0; i < main; i++) ls.push('https://' + DJ_W[i] + '.' + suf[0]);
  for (i = 0; ls.length < n && suf[1]; i++) ls.push('https://' + DJ_W[6 + i] + '.' + suf[1]);
  return { list: ls, suf: suf, cached: cached };
}

function djProbe(u) {
  var h = djGet(u, 5000);
