<span class="comment-time">${formatTime($.created_at)}</span></div>
<div class="like_counts"><span>♡${formatCount($.attitudes_count)}</span></div>
</div>
<div class="comment-text">${$.text.replace(/https?:\/\/m.weibo.cn\/\d+\/(\d+)/g,'https://m.weibo.cn/a/$1').replace(/'\/n\//g,"'https://m.weibo.cn/n/")}</div>
${galleryItems}
${videos}

</div>`;

}

function liveUrl(href){
	const {java} = this
