function replaceLink(str){
	const {java} = this;
	let linkstyle = 'style="color:#1E88E5"';
	   return String(str)
//用户链接

.replace(/href=['"][^"]+?weibo.(?:com|cn)\/(u|profile)\/(\d+)['"]/g,`onclick='openUser("$1")' ${linkstyle}`)
.replace(/href=['"]([^'"]+?weibo.(?:com|cn)\/n\/[^"']+)['"]/g,`onclick='openUser("$1")' ${linkstyle}`)

//话题链接

.replace(/href=['"][^"']+?(?:containerid=(?:231522|100103)type%3D1|s.weibo.com\/weibo\?q=)[^"']+?%23(.*?)%23[^'"]*?['"]/g, 
    function(match, p1) {

        if(match.includes('ai.s.weibo.com/api') || match.includes('m.s.weibo.com/applink')) {
            return match;
        }


        let decoded = decodeURIComponent(p1);   
        return `onclick='openUser("#${decoded}#")' ${linkstyle}`;
    }
)

//正文链接
.replace(/href=['"][^'"]*?(?:m\.weibo\.cn|weibo\.com)*\/(?:\d+\/\d+|a|status|detail\/\d+|(?:\d+|status)\/[a-zA-Z\d]{9,18})[^'"]*?['"]/g,function(match, p1) {

   var match1 = match.match(/\/(\d+)\??"$/);
		var match2 = match.match(/(?:\d+|status)\/([a-zA-Z\d]{9,13})\??/);
        var id = match1 ? match1[1] : (match2 ? match2[1] : "");
        if(id == "" || match.includes('ai.s.weibo.com/api') || match.includes('m.s.weibo.com/applink')){
        	   return match
        	}
        return `onclick='openContent("${id}")' ${linkstyle}`;
    })

//超话链接
.replace(/href=['"][^'"]+?(?:containerid=|\/p\/)([\da-z]{30,60})[^'"]*?['"]/g,`onclick='openUser("$1")' ${linkstyle}`);

}


