    filterUsers(keyword) {
        const listContainer = document.getElementById('follow-list-container');
        const userItems = listContainer.querySelectorAll('.user-item');

        if (!keyword.trim()) {
            userItems.forEach(item => {
                item.style.display = 'flex';
            });
            return;
        }

        const searchTerm = keyword.toLowerCase();
        userItems.forEach(item => {
            const name = item.querySelector('.user-name').textContent.toLowerCase();
            const remark = item.querySelector('.user-remark')
            const remarkName = remark?remark.textContent.toLowerCase():"";

            if (name.includes(searchTerm) || remarkName.includes(searchTerm)) {
                item.style.display = 'flex';
            } else {
                item.style.display = 'none';
            }
        });
    }

    renderUserList() {
        const listContainer = document.getElementById('follow-list-container');

        this.users.forEach((user, index) => {
            if (document.getElementById(`user-${user.id}`)) {
                return;
            }

            const userItem = document.createElement('div');
            userItem.id = `user-${user.id}`;
            userItem.className = 'user-item';
            userItem.dataset.index = index;

            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.className = 'user-checkbox';
            checkbox.checked = this.selectedUsers.has(user.id);
            checkbox.onchange = (e) => {
                e.stopPropagation();
                this.toggleUserSelection(user.id, checkbox.checked);
            };
            const avatar = document.createElement('img');
            avatar.className = 'user-avatar';
            avatar.src = user.avatar;
            avatar.alt = user.name;
            avatar.onerror = () => {
                avatar.src = 'data:image/svg+xml;base64,';
            };

            const userInfo = document.createElement('div');
            userInfo.className = 'user-info';

            const userName = document.createElement('div');
            userName.className = 'user-name';
            userName.textContent = user.name;
            userName.title = user.name;


            let remarkName = "";

            if(user.remarkName){
                remarkName = document.createElement('p');
                remarkName.className = 'user-remark';
                remarkName.textContent = "备注: "+ user.remarkName;
            }


            const userFollowers = document.createElement('div');
            userFollowers.className = 'user-followers';
            userFollowers.innerHTML = (remarkName?remarkName.outerHTML : "")
                                                        + user.desc;

            userInfo.appendChild(userName);
            userInfo.appendChild(userFollowers);
            const subscribeBtn = document.createElement('button');
            subscribeBtn.className = `subscribe-btn ${user.isSubscribed ? 'subscribed' : ''}`;
            subscribeBtn.textContent = user.isSubscribed ? '已订阅' : '订阅';
            subscribeBtn.onclick = (e) => {
                e.stopPropagation();
                this.subscribeUser(user,'0');
                subscribeBtn.textContent = '已订阅';
                subscribeBtn.className = 'subscribe-btn subscribed';
                user.isSubscribed = true;
            };

            userItem.appendChild(checkbox);
            userItem.appendChild(avatar);
            userItem.appendChild(userInfo);
            userItem.appendChild(subscribeBtn);
            userItem.onclick = (e) => {
                if (e.target !== checkbox && e.target !== subscribeBtn) {
                    checkbox.checked = !checkbox.checked;
                    this.toggleUserSelection(user.id, checkbox.checked);
                }
            };

            listContainer.appendChild(userItem);
        });
    }

    checkIfSubscribed(userId) {

        let subscribedUsers = JSON.parse(source.getVariable() || '{"users":[],"topics":[],"superTopics":[]}').users;

        return subscribedUsers.some(user => 
            user && user.id && String(user.id) === String(userId)
        );
    }

    toggleUserSelection(userId, isSelected) {
        if (isSelected) {
            this.selectedUsers.add(userId);
            const checkbox = document.querySelector(`#user-${userId} .user-checkbox`);
            if (checkbox) {
                checkbox.checked = true;
            }
            const userItem = document.getElementById(`user-${userId}`);
            if (userItem) {
                userItem.classList.add('selected');
            }
        } else {
            this.selectedUsers.delete(userId);
            const checkbox = document.querySelector(`#user-${userId} .user-checkbox`);
            if (checkbox) {
                checkbox.checked = false;
            }
            const userItem = document.getElementById(`user-${userId}`);
            if (userItem) {
                userItem.classList.remove('selected');
            }
        }

        this.updateStatus();
    }

    selectAllUsers() {
        this.users.forEach(user => {
            this.selectedUsers.add(user.id);
            const checkbox = document.querySelector(`#user-${user.id} .user-checkbox`);
            if (checkbox) {
                checkbox.checked = true;
            }
            const userItem = document.getElementById(`user-${user.id}`);
            if (userItem) {
                userItem.classList.add('selected');
            }
        });
        this.updateStatus();
    }

    deselectAllUsers() {
        this.selectedUsers.clear();
        document.querySelectorAll('.user-checkbox').forEach(checkbox => {
            checkbox.checked = false;
        });
        document.querySelectorAll('.user-item').forEach(item => {
            item.classList.remove('selected');
        });
        this.updateStatus();
    }

    updateStatus() {
        const statusText = document.getElementById('status-text');
        const batchBtn = document.querySelector('.batch-subscribe');

        if (statusText) {
            const total = this.users.length;
            const selected = this.selectedUsers.size;
            statusText.textContent = `已选择 ${selected} 个用户，共 ${total} 个`;
        }

        if (batchBtn) {
            batchBtn.disabled = this.selectedUsers.size === 0;
        }
    }

    subscribeUser(user,type) {
        let jsonData = JSON.parse(source.getVariable() || '{"users":[],"topics":[],"superTopics":[]}');
       let existingUser = jsonData["users"].find(u => String(u.id) === user.id);
    if (!existingUser) {
        jsonData["users"].push(user);
        source.putVariable(JSON.stringify(jsonData))
    }
        if(type==='0')this.showToast(`已订阅用户: ${user.name}`);
        currentData = JSON.parse(source.getVariable() || '{"users":[],"topics":[],"superTopics":[]}').users;
        renderSubscribeList(currentData);
    }

    batchSubscribe() {
        if (this.selectedUsers.size === 0) {
            this.showToast('请先选择要订阅的用户');
            return;
        }

        const userIds = Array.from(this.selectedUsers);
        const userNames = userIds.map(id => {
            const user = this.users.find(u => u.id === id);
            return user ? user.name : '未知用户';
        }).slice(0, 3); 

        const confirmMsg = userIds.length <= 3 
            ? `确定要订阅以下用户吗？\n${userNames.join('\n')}`
            : `确定要订阅选中的 ${userIds.length} 个用户吗？\n包括：${userNames.join('、')}等`;

        if (confirm(confirmMsg)) {
            userIds.forEach(userId => {
                const userItem = document.getElementById(`user-${userId}`);
                if (userItem) {
                    const btn = userItem.querySelector('.subscribe-btn');
                    if (btn) {
                        btn.textContent = '已订阅';
                        btn.className = 'subscribe-btn subscribed';
                    }
                }
            });

            this.showToast(`成功订阅了 ${userIds.length} 个用户！`);

       userIds.forEach(id => {
            const user = this.users.find(u => u.id === id);
            if(user){
                this.subscribeUser(user);
            }
        })

            this.deselectAllUsers();
        }
    }

    showToast(message) {
        const oldToast = document.getElementById('weibo-toast');
        if (oldToast) {
            document.body.removeChild(oldToast);
        }

        const toast = document.createElement('div');
        toast.id = 'weibo-toast';
        toast.textContent = message;
        toast.style.cssText = `
            position: fixed;
            bottom: 50px;
            left: 50%;
            transform: translateX(-50%);
            background: rgba(0, 0, 0, 0.8);
            color: white;
            padding: 12px 24px;
            border-radius: 6px;
            font-size: 14px;
            z-index: 10001;
            animation: toastFadeInOut 2s ease;
        `;

        const style = document.createElement('style');
        style.textContent = `
            @keyframes toastFadeInOut {
                0% { opacity: 0; transform: translate(-50%, 20px); }
                20% { opacity: 1; transform: translate(-50%, 0); }
                80% { opacity: 1; transform: translate(-50%, 0); }
                100% { opacity: 0; transform: translate(-50%, -20px); }
            }
        `;
        document.head.appendChild(style);

        document.body.appendChild(toast);

        setTimeout(() => {
            if (toast.parentNode) {
                document.body.removeChild(toast);
            }
            if (style.parentNode) {
                document.head.removeChild(style);
            }
        }, 2000);
    }

}

