(function() {
 'use strict';

 if (window.__Injected) return;
 window.__Injected = true;

 /* ===== 宿主适配层 ===== */
 const Host = {
  vibrate(ms) { try { if (!navigator.vibrate) return; if (navigator.userActivation && !navigator.userActivation.hasBeenActive) return; navigator.vibrate(ms); } catch (e) {} }, 
  ajax(u) { u = String(u); if (typeof java !== 'undefined' && java?.ajax) { try { return java.ajax(u); } catch (e) {} } return fetchAjax(u); }, 
  ajaxAsync(u, t) { try { return ajaxAwait(String(u), t || 15000); } catch (e) { return Promise.resolve().then(() => Host.ajax(String(u))); } }, 
  toast(m) { try { java.toast(String(m)); } catch (e) {} },
  open(k, u, t) { try { if (t) java.open(String(k), String(u), String(t)); 
   else java.open(String(k), String(u)); } catch (e) {} },
  openUrl(u) { try { java.openUrl(String(u)); } catch (e) {} },
  connect(u) { try { java.connect(String(u)); } catch (e) {} },
  showPhoto(u) { try { java.showPhoto(String(u)); } catch (e) {} },
  getVariable() { try { return source.getVariable() || ''; } catch (e) { return ''; } },
  putVariable(v) { try { source.putVariable(String(v)); return true; } catch (e) { return false; } },
  downloadFile(u) { try { return java.downloadFile(String(u)); } catch (e) { return null; } }, 
  base64Encode(s) { try { return java.base64Encode(String(s)); } catch (e) { return ''; } }, 
  openVideoPlayer(u, t, b) { try { java.openVideoPlayer(String(u), String(t), b); } catch (e) {} }, 
 };

/* ===== 外部变量 ===== */
const TuiImg = typeof TuiImgData === 'undefined' ? '推' : TuiImgData;
const LeiImg = typeof LeiImgData === 'undefined' ? '雷' : LeiImgData;
const CuaiEmo = typeof cuaiEmo === 'undefined' ? '' : cuaiEmo;
const CmtImg = typeof commentImg === 'undefined' ? '𝙃𝙊𝙏 𝘾𝙊𝙈𝙈𝙀𝙉𝙏' : commentImg;

 /* ===== 常量 ===== */
 const SCHEMA_VERSION = 1;

 const LONG_PRESS_MS = 500;
 const LONG_PRESS_SLOP = 10;
 const VIBRATE_MS = 50;

 const VIEWER_MIN_SWIPE = 50;
 const VIEWER_LOCK_MS = 350;

 const ALL_L2_MAX = 10;
 const COMMENTS_MIN = 5;

 var DEFAULT_EMO = {
  '[更新求踢]': CuaiEmo
 };

 const API = {
  BLOG: 'https://api.lofter.com/v2.0/blogHomePage.api',
  POST: 'https://api.lofter.com/oldapi/post/detail.api',
  COLL: 'https://api.lofter.com/v1.1/postCollection.api',
  GIFT: 'https://api.lofter.com/v1.1/trade/gift/post/newSupportInfo',
  L1: 'https://api.lofter.com/comment/l1/page.json',
  L2: 'https://api.lofter.com/comment/l2/page/abtest.json',
  PARA: 'https://api.lofter.com/comment/pCommentList.json',
  HOT: 'https://api.lofter.com/comment/hotComment.json',
  COUNTS: 'https://api.lofter.com/comment/pCommentCounts.json',
  EMOTES: 'https://api.lofter.com/newapi/emotes.json',
  AUDIO: 'https://api.lofter.com/newapi/post/audio/'
 };
 const WBI = {
  haha: 'https://face.t.sinajs.cn/t4/appstyle/expression/ext/normal/c5/201810_haha_mobile.png',
  bitter: 'https://face.t.sinajs.cn/t4/appstyle/expression/ext/normal/87/201810_lei_mobile.png',
  sweet: 'https://face.t.sinajs.cn/t4/appstyle/expression/ext/normal/79/2022_wow_mobile.png',
  ping: 'https://face.t.sinajs.cn/t4/appstyle/expression/ext/normal/ce/201810_bingbujiandan_mobile.png'
 };

 /* ===== 通用工具 ===== */
 function trimStr(s) { return String(s == null ? '' : s).trim(); }
 /* 正则元字符转义 */
 function reEsc(s) { return String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
 /* 读取隐藏 input 的值 */
 function val(id) { const e = document.getElementById(id); return e ? e.value : ''; }
 /* HTML 转义 */
 function esc(s) {
  if (s == null) return '';
  return String(s)
   .replace(/&/g, '&amp;')
   .replace(/</g, '&lt;')
   .replace(/>/g, '&gt;')
   .replace(/"/g, '&quot;')
   .replace(/'/g, '&#39;');
 }
 /* 时间戳格式化 */
 function fmtTime(ts) {
 const n = Number(ts);
 if (!n) return '';
 const d = new Date(n + 8 * 36e5),
  z = v => String(v).padStart(2, '0');
 return `${d.getUTCFullYear()}-${z(d.getUTCMonth()+1)}-${z(d.getUTCDate())} ${z(d.getUTCHours())}:${z(d.getUTCMinutes())}:${z(d.getUTCSeconds())}`; 
}

 /* 过滤危险 URL */
 function safeUrl(u) {
  if (!u) return '';
  u = String(u);
  if (/^https?:\/\//i.test(u)) return u;
  if (/^\/\//.test(u)) return 'https:' + u;
  if (/^data:image\//i.test(u)) return u;
  return '';
 }

 /* java.ajax 降级通道 */
 function fetchAjax(u){
 if(typeof fetch!='function')return null;
 let i={credentials:'include'},url=u;
 try{
  const p=u.match(/^(.*?)\?product=([^,]*),(.+)$/);
  if(p){
   const o=JSON.parse(p[3]),m=(o.method||'GET').toUpperCase();
   url=p[1]+'?product='+encodeURIComponent(p[2]);
   i.method=m;
   i.headers=Object.fromEntries(Object.entries(o).filter(([k])=>!/^(method|body|accept-encoding|content-length|host|connection|user-agent|origin|referer|cookie)$/i.test(k)));
   if(o.body!=null&&!/^(GET|HEAD)$/.test(m)){i.body=''+o.body;i.headers['Content-Type']||='application/x-www-form-urlencoded'}
  }
  return fetch(url,i).then(r=>r?.ok?r.text():null).catch(()=>null)
 }catch{return null}
}

 /* 调整头像 URL */
 function avaUrl(b) {
  const u = safeUrl(b);
  if (!u) return '';
  if (u.indexOf('?')) return u;
  return u + '?imageView&thumbnail=84x84&stripmeta=0&quality=90&type=webp'; 
 }

 /* Body 滚动锁 */
 let _lockScrollY = 0;
 let _lockBarWidth = 0;
 let _scrollLocked = false;

 function lockBodyScroll() {
  if (_scrollLocked) return;
  _scrollLocked = true;
  _lockScrollY = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
  _lockBarWidth = window.innerWidth - document.documentElement.clientWidth;
  document.body.style.overflow = 'hidden';
  if (_lockBarWidth > 0) document.body.style.paddingRight = _lockBarWidth + 'px';
 }

 function unlockBodyScroll() {
  if (!_scrollLocked) return;
  _scrollLocked = false;
  document.body.style.overflow = '';
  document.body.style.paddingRight = '';
  const y = window.scrollY || window.pageYOffset || document.documentElement.scrollTop || 0;
  if (y !== _lockScrollY) window.scrollTo(0, _lockScrollY);
  _lockScrollY = 0;
  _lockBarWidth = 0;
 }

 /* ===== Store：单一状态源 ===== */
 const Store = (function() {
  const state = { tags: [], collections: [], authors: [], articles: [] };
  // const dirty = new Set();
  // let flushTimer = null;
  let lastRaw = '';
  let corrupted = false;

  /* 读变量并解析，返回 {ok, cfg} */
  function readRaw() {
   const raw = Host.getVariable();
   if (!raw || !raw.trim()) return { ok: true, cfg: {} };
   try {
    const p = JSON.parse(raw);
    if (!p || typeof p !== 'object' || Array.isArray(p)) return { ok: false };
    return { ok: true, cfg: p };
   } catch (e) { return { ok: false }; }
  }

  /* 全量载入变量到 State */
  function load() {
   const raw = Host.getVariable();
   lastRaw = raw;
   const { ok, cfg } = readRaw();
   corrupted = !ok;
   if (!ok) {
    state.tags = [];
    state.collections = [];
    state.authors = [];
    state.articles = [];
    return;
   }
   const arr = v => Array.isArray(v) ? v : [];
   state.tags = arr(cfg.tags).map(trimStr).filter(Boolean);
   state.collections = arr(cfg.collections).filter(c => c && c.name && c.id);
   state.authors = arr(cfg.authors).filter(a => a && a.name && a.blogId);
   state.articles = arr(cfg.articles).filter(a => a && a.title && a.url);
  }

  /* 若变量外部已变，重新 Load */
  function reload() {
   const raw = Host.getVariable();
   if (raw === lastRaw) return false;
   load();
   return true;
  }

  /* 原子追加 */
  function add(field, item, dupFn, opts) {
   const { ok, cfg } = readRaw();
   if (!ok) { corrupted = true; return 'corrupt'; }

   const latest = cfg || {};
   if (!Array.isArray(latest[field])) latest[field] = [];

   if (dupFn && latest[field].some(dupFn)) {
    // 同步本地，UI 的"已存在"判断才准确
    state[field] = latest[field];
    return 'dup';
   }

   if (opts && opts.prepend) latest[field].unshift(item);
   else latest[field].push(item);
   latest.version = SCHEMA_VERSION;

   const payload = JSON.stringify(latest);
   try {
    const r = JSON.parse(payload);
    if (!r || typeof r !== 'object' || Array.isArray(r)) return 'fail';
   } catch (e) { return 'fail'; }

   if (!Host.putVariable(payload)) return 'fail';

   state[field] = latest[field];
   lastRaw = Host.getVariable();
   corrupted = false;
   return 'ok';
  }

  load();

  return {
   state, load, reload, add, isCorrupted() { return corrupted; }
  };
 })();

 /* ===== 表情替换：key → <img> ===== */
 const Emo = (function() {
  /*let _emotes = null;*/
  function mk() {
   /*if(!_emotes){_emotes = {}; try{JSON.parse(Host.ajax(API.EMOTES)).data.packages.forEach(p => p.emotes.forEach(e => e.name && e.url && (_G[e.name] = e.url)));}catch(e){}}*/
   return Object.assign({}, DEFAULT_EMO /*, _emotes*/ );
  }

  /* 从条目里收集 emotes 到 map */
  function pick(it, m) {
   if (!it || !m || !Array.isArray(it.emotes)) return;
   it.emotes.forEach(e => {
    if (e && e.name && e.url) m[e.name] = e.url;
   });
  }
  /* 长 key 优先，避免短 key 抢先匹配 */
  function sub(s, m) {
   if (!s || !m) return s;
   const keys = Object.keys(m);
   if (!keys.length) return s;
   keys.sort((a, b) => b.length - a.length);
   const pattern = new RegExp(keys.map(reEsc).join('|'), 'g');
   return s.replace(pattern, k => {
    const u = safeUrl(m[k]);
    if (!u) return k;
    return `<img class="emo" src="${esc(u)}" alt="${esc(k)}" title="${esc(k)}" onerror="this.style.display='none';this.nextElementSibling.style.display='inline'"><span style="display:none">${esc(k)}</span>`;
   });
  }

  /* 信任服务端清洗结果，仅做表情替换 */
  function render(html, m) { return sub(html || '', m); }
  return { mk, pick, sub, render };
 })();

 /* 替换 [表情] / [图片] 占位符 */
 function replaceCMImages(content, images) {
  if (!content || !images || images.length === 0) return content;
  var imgHtml = buildCMImages(images);
  if (!imgHtml) return content;
  return content.replace(/\[(表情|图片)\]/g, imgHtml);
 }
 function buildCMImages(images, wrap) {
  if (wrap === undefined) wrap = true;
  if (!images || images.length === 0) return '';
  var imgs = '';
  for (var i = 0; i < images.length; i++) {
   var url = images[i] && (images[i].orign || images[i].raw || images[i].url || '');
   if (url) imgs += `<img class="cm-img" src="${esc(url)}" loading="lazy" onclick="java.showPhoto('${esc(url)}')"  onerror="this.style.opacity='0'">`;
  }
  if (!imgs) return '';
  return wrap ? `<div class="cm-imgs">${imgs}</div>` : imgs;
 }

 /* ===== 添加：标签 / 合集 / 作者 / 文章 ===== */
 function notifyAdd(kind, name, r) {
  if (r === 'ok') Host.toast(`${kind}「${name}」添加完成！`);
  else if (r === 'dup') Host.toast(`${kind}「${name}」已订阅`);
  else if (r === 'corrupt') Host.toast('变量损坏，无法写入');
  else Host.toast('写入失败，请重试');
 }
 function addTag(t) {
  t = trimStr(t);
  if (!t) return;
  notifyAdd('标签', t, Store.add('tags', t, x => x === t));
 }
 function addCol(n, id) {
  n = trimStr(n);
  id = trimStr(id);
  if (!n || !id) return Host.toast('合集信息不完整');
  notifyAdd('合集', n, Store.add('collections', { name: n, id }, x => x && String(x.id) === id));
 }
 function addAuthor(b, n, a) {
  b = trimStr(b);
  n = trimStr(n);
  if (!b || !n) return Host.toast('作者信息不完整');
  notifyAdd('作者', n, Store.add('authors', { name: n, blogId: b, avatar: a || '' },
   x => x && String(x.blogId) === b));
 }
 function addArticle(t, u) {
  t = trimStr(t);
  u = trimStr(u);
  if (!t) {
   const el = document.querySelector('.post-author__name');
   const a = el ? el.textContent.trim() : '';
   t = a ? `『${a}』的作品` : '无题';
  }
  if (!u) return Host.toast('文章链接缺失');
  notifyAdd('文章', t, Store.add('articles', { title: t, url: u }, x => x && x.url === u, { prepend: true }));
 }

 /* ===== 共享数据 ===== */
 /* 以签名检测失效，支持 SPA */
 let _sharedCache = null;
 let _sharedSig = '';

 function shared() {
  const sig = [val('blogId'), val('article-url'), val('collection-id')].join('|');
  if (_sharedCache && _sharedSig === sig) return _sharedCache;
  _sharedSig = sig;
  _sharedCache = {
   author: { blogId: val('blogId'), name: val('author-name'), avatar: val('author-avatar') },
   article: { title: val('article-title'), url: val('article-url') },
   collection: { blogId: val('blogId'), name: val('collection-name'), id: val('collection-id') }
  };
  return _sharedCache;
 }

 /* ===== 链接路由 ===== */
 function openBlog(id) {
  id = trimStr(id);
  if (!id) return false;
  const info = /^\d+$/.test(id) ? `targetblogid=${id}` : `blogdomain=${id}`;
  const body = `supportposttypes=1%2C2%2C3%2C4%2C5%2C6&${info}&offset={{(page-1)*18}}&method=getPostLists&postdigestnew=1&returnData=1&limit=18&checkpwd=1&needgetpoststat=1`;
  Host.open('sort', `${API.BLOG}?product=lofter-android-7.4.4,${JSON.stringify({ method:'POST', body })}`);
  return true;
 }
 /* 链接路由到原生页面（文章正文 / 合集列表 / 作者列表） */
 function routeLink(u, t) {
  if (!u) return false;
  // 短链提取
  if (/\/\/s\.lofter\.com\/-s\//i.test(u)) { 
   var raw = ''; try { raw = String(Host.connect(u)); } 
   catch (e) { raw = String(e && e.message || e); } 
   var m = raw.match(/url=(\S+?)}/); if (m && m[1] !== u) {u = m[1];} 
  }

  if (u.indexOf('//') === 0) u = 'https:' + u;
  const post = u.match(/https?:\/\/([^.]+)\.lofter\.com\/post\/([0-9a-fA-F]+)_([0-9a-fA-F]+)/);
  if (post) {
   const body = `targetblogid=${parseInt(post[2],16)}&blogdomain=${post[1]}.lofter.com&postid=${parseInt(post[3],16)}`; 
   Host.open('rss', `${API.POST}?product=lofter-android-8.3.64,${JSON.stringify({ method:'POST','accept-encoding':'gzip, deflate', body })}`, t);
   return true;
  }
  const col = u.match(/collectionId=(\d+)/);
  if (col && /front\/blog\/collection/.test(u)) {
   Host.open('sort', `${API.COLL}?product=lofter-android-8.0.2&method=getCollectionDetail&offset={{(page-1)*45}}&limit=45&collectionid=${col[1]}`);
   return true;
  }
  const bid = u.match(/blogId=(\d+)/);
  if (bid) return openBlog(bid[1]);

  const hp = u.match(/lofter\.com\/front\/blog\/home-page\/([^/?#]+)/);
  if (hp) {
   const n = hp[1].replace(/\.lofter\.com$/i, '');
   return n && n !== 'www' ? openBlog(`${n}.lofter.com`) : false;
  }
  const home = u.match(/^https?:\/\/(.+?)\.lofter\.com\/?$/);
  if (home && home[1] !== 'www') return openBlog(`${home[1]}.lofter.com`);
  return false;
 }

 /* ===== 图片查看器：点击切换 / 左右滑动 ===== */
 const Viewer = (function() {
 function initOne(v) {
  if (v.dataset.ivBound === '1') return;
  v.dataset.ivBound = '1';
  const slides = Array.from(v.querySelectorAll('.iv-slide'));
  if (!slides.length) return;
  const n = slides.length;
  let i = 0, lock = false, vert = false;

  function go(next) {
   if (lock || vert || n <= 1) return;
   next = ((next % n) + n) % n;
   if (next === i) return;
   lock = true;
   slides[i].classList.remove('active');
   i = next;
   slides[i].classList.add('active');
   setTimeout(() => { lock = false; }, VIEWER_LOCK_MS);
  }
  v.addEventListener('click', e => {
   if (e.target.closest('.iv-page')) {
    e.stopPropagation();
    if (n <= 1) return;
    vert = !vert;
    v.classList.toggle('iv-vertical', vert);
    slides.forEach((s, k) => s.classList.toggle('active', vert || k === i));
    return;
   }
   go(i + 1);
  });

  let sx = 0, sy = 0;
  v.addEventListener('touchstart', e => {
   sx = e.touches[0].clientX;
   sy = e.touches[0].clientY;
  }, { passive: true });
  v.addEventListener('touchend', e => {
   if (vert) return;
   const dx = e.changedTouches[0].clientX - sx;
   const dy = e.changedTouches[0].clientY - sy;
   if (Math.abs(dx) > VIEWER_MIN_SWIPE && Math.abs(dx) > Math.abs(dy)) {
    go(i + (dx < 0 ? 1 : -1));
   }
  }, { passive: true });
 }

 function scan() { document.querySelectorAll('.iv').forEach(initOne); }
 return { scan };
})();

 /* ===== 异步请求：一次重试 ===== */
 const REQ_RETRY = 1;
const REQ_RETRY_DELAY = 250;
const REQ_TIMEOUT = 15000;

async function requestRaw(url, timeout) {
 for (let i = 0; i <= REQ_RETRY; i++) {
  const raw = await Host.ajaxAsync(url, timeout || REQ_TIMEOUT);
  if (raw) return raw;
  if (i < REQ_RETRY) await new Promise(r => setTimeout(r, REQ_RETRY_DELAY * (i + 1)));
 }
 return null;
}
async function ajaxJson(url, timeout) {
 const raw = await requestRaw(url, timeout);
 if (!raw) return null;
 try { return JSON.parse(raw); } catch (e) { return null; }
}

