   </div>
   <div class="cm-body">${replaceCMImages(Emo.render(it.content, m),im)}</div>
   <div class="cm-foot sp">
    <span class="cm-like">${like}</span>
    <span class="cm-meta">${esc(t)} ${it.ipLocation || ''}</span>
   </div>`;
   // if (it.l2Count > 0) h += '<div class="cm-rp-container"></div>';
   if (it.l2Count > 0) h += `<div class="cm-rp-container" data-loaded="0"><div class="cm-rp-hint">共 ${it.l2Count} 条回复</div></div>`; 
   return h + '</div>';
  },

  /* 精简评论 */
  hot(it, m) {
   return `<div class="cm">
   <div class="cm-body">${Emo.render(it.content, m)}</div>
   <div class="cm-foot">${esc(it.commentHot || '')} <i class="fa fa-heart" aria-hidden="true"></i></div>
  </div>`;
  },

  list(arr, postId, blogId, isPop) {
   const m = Emo.mk();
   return arr.map(it => {
    Emo.pick(it, m);
    return CR.item(it, m, postId, blogId, !!isPop);
   }).join('');
  }
 };

 /* ===== 初始评论加载（迁移） ===== */
 async function loadInitialComments() {
  const postId = val('postId');
  const blogId = val('blogId');
  if (!postId || !blogId) return;
  /* 读评论模式：'0' 最新 / '1' 热门 / '' 精简 / '-1' 关闭 */
  let mode = '0';
  try {
   const raw = Host.getVariable();
   const cfg = (raw && raw.trim()) ? JSON.parse(raw) : {};
   if (cfg.comments !== undefined && cfg.comments !== null) mode = String(cfg.comments);
  } catch (e) {}
  const section = document.querySelector('.comments');
  if (!section) return;
  if (section.querySelector('.cm')) return;
  section.setAttribute('data-mode', mode);
  if (mode === '-1') return;
  const isHot = (mode === '1');
  const hidden = (mode === '');
  const r = await CmtApi.l1(postId, blogId, 0);
  const emoteMap = Emo.mk();
  (r.list || []).forEach(it => Emo.pick(it, emoteMap)); // 简评引用
  (r.hot || []).forEach(it => Emo.pick(it, emoteMap));
  let choiceHtml = '';
  let mainHtml = '';
  if (!isHot) {
   const hotList = await CmtApi.hot(postId, blogId);
   if (hotList.length) {
    hotList.forEach(it => Emo.pick(it, emoteMap));
    choiceHtml = CmtImg +
     hotList.map(it => CR.hot(it, emoteMap)).join('');
   }
  }
  if (!hidden) {
   var target = isHot ? (r.hot && r.hot.length ? r.hot : r.list) : r.list;
   if (target && target.length) {
    target.forEach(it => Emo.pick(it, emoteMap)); // ？未调用
    // 🔆
    const title = isHot ? '<b><em>热门评论</em></b>' : '<b><em>最新评论</em></b>';
    mainHtml = title + CR.list(target, postId, blogId);
   }
  }
  section.innerHTML = choiceHtml + mainHtml;
  if (!hidden && !isHot) { section.dataset.l1Offset = String((target || []).length); }
  fillEmptyReplies(postId, blogId, false);
  fillQuotes();
  initMoreComments();
 }

 /* ===== 段评标记加载（迁移） ===== */
 async function loadCommentCounts() {
  const postId = val('postId');
  const blogId = val('blogId');
  if (!postId || !blogId) return;

  // 关闭评论时不加载段评标记
  let mode = '0';
  try {
   const raw = Host.getVariable();
   const cfg = (raw && raw.trim()) ? JSON.parse(raw) : {};
   if (cfg.comments !== undefined && cfg.comments !== null) mode = String(cfg.comments);
  } catch (e) {}
  if (mode === '-1') return;

  const list = await CmtApi.counts(postId, blogId);
  if (!list.length) return;

  const map = {};
  list.forEach(it => {
   if (it.pid) map[it.pid] = {
    count: it.count || 0,
    hahaNum: it.hahaNum || 0,
    sweetNum: it.sweetNum || 0,
    bitterNum: it.bitterNum || 0
   };
  });

  const paras = document.querySelectorAll('.post-content p');
  paras.forEach((p, idx) => {
   const fallbackPid = 'p_i' + idx;
   const actualPid = p.id || fallbackPid;
   const info = map[actualPid] || map[fallbackPid];
   if (!info) return;
   if (p.querySelector('.cm-mark')) return;

   let text = '',
    type = '';
   if (info.count > 0) {
    text = `<span class="emo-word-fb">评论</span>${info.count}+`;
    type = 'comment';
   } else {
    const emos = [
     { t: 'haha', l: '哈哈哈', v: info.hahaNum, img: WBI.haha },
     { t: 'bitter', l: '好虐', v: info.bitterNum, img: WBI.bitter },
     { t: 'sweet', l: '真甜', v: info.sweetNum, img: WBI.sweet },
    ];
    let max = emos[0];
    for (let e = 1; e < emos.length; e++)
     if (emos[e].v > max.v) max = emos[e];
    if (max.v > 0) {
     const face = `<img class="emo-word" src="${max.img}" alt="${max.l}" onerror="this.style.display='none';this.nextElementSibling.style.display='inline'"><span class="emo-word-fb">${max.l}</span>`;
     text = `${face}×${max.v}`;
     // text = `${max.l}×${max.v}`;
     type = max.t;
    }
   }
   if (!text) return;

   const marker = document.createElement('span');
   marker.className = 'cm-mark';
   marker.setAttribute('data-pid', actualPid);
   marker.setAttribute('data-count-type', type);
   marker.setAttribute('data-has-comments', info.count > 0);
   marker.setAttribute('data-count', info.count);
   marker.setAttribute('data-haha', info.hahaNum);
   marker.setAttribute('data-sweet', info.sweetNum);
   marker.setAttribute('data-bitter', info.bitterNum);
   marker.innerHTML = text;
   p.appendChild(marker);
  });
 }

 /* ===== 次级评论异步填充 ===== */
 async function loadRepliesInto(container, postId, blogId, commentId, full, pending) {
 try { let list, total;
  if (full) { list = pending ? await pending 
   : await CmtApi.allL2(postId, blogId, commentId); 
   total = list.length;
  } else { const r = pending ? await pending 
   : await CmtApi.l2(postId, blogId, commentId, 0); 
   list = r.list; const cm = container.closest('.cm');
   total = cm ? (parseInt(cm.dataset.l2count, 10) || list.length) 
   : list.length; 
  }

  const m = Emo.mk();
  list.forEach(x => Emo.pick(x, m));
  let html = list.map(x => CR.reply(x, m, full)).join('');
  if (!full && total > list.length) {
   html += `<div class="cm-more-rp" data-comment-id="${esc(commentId)}" data-offset="${list.length}" data-total="${total}">加载更多回复（已显示 ${list.length}/${total}）</div>`; 
  } 
  container.innerHTML = html || '';
 } catch (e) { /* 静默失败 */ container.innerHTML = ''; }
}

 async function fillEmptyReplies(postId, blogId, full) {
 const containers = document.querySelectorAll('.cm-rp-container[data-loaded="0"]');
 for (const c of containers) {
  const cm = c.closest('.cm'); if (!cm) continue;
  const cid = cm.dataset.commentId; 
  const cnt = parseInt(cm.dataset.l2count, 10) || 0;
  if (cid && cnt > 0) { c.dataset.loaded = '1'; 
   await loadRepliesInto(c, postId, blogId, cid, full);
 }}
}

async function fillEmptyReplies(postId, blogId, full) {
 const jobs = [];
 document.querySelectorAll('.cm-rp-container[data-loaded="0"]').forEach(c => { 
  const cm = c.closest('.cm'); if (!cm) return;
  const cid = cm.dataset.commentId;
  const cnt = parseInt(cm.dataset.l2count, 10) || 0;
  if (cid && cnt > 0) { c.dataset.loaded = '1';
   const pending = full ? CmtApi.allL2(postId, blogId, cid) 
   : CmtApi.l2(postId, blogId, cid, 0); 
   jobs.push({ c, cid, pending });
 }});
 for (const j of jobs) { await loadRepliesInto(j.c, postId, blogId, j.cid, full, j.pending); } 
}

 /* ===== 加载更多：回复 / 评论 ===== */
 async function moreReplies(btn) {
  if (!btn || btn.classList.contains('disabled')) return;
  const cid = btn.dataset.commentId;
  const total = parseInt(btn.dataset.total, 10) || 0;
  const off = parseInt(btn.dataset.offset, 10) || 0;
  if (!cid || off >= total) { btn.remove(); return; }

  const p = CmtApi.params();
  if (!p) {
   btn.classList.add('disabled');
   btn.textContent = '参数获取失败';
   return;
  }

  btn.classList.add('disabled');
  btn.textContent = '加载中...';
  const r = await CmtApi.l2(p.postId, p.blogId, cid, off);
  if (!r.list.length) {
   btn.textContent = '没有更多回复了';
   setTimeout(() => btn.remove(), 500);
   return;
  }
  const m = Emo.mk();
  r.list.forEach(x => Emo.pick(x, m));
  const box = btn.closest('.cm-rp-container') || btn.parentNode;
  const seen = new Set(Array.from(box.querySelectorAll('.cm-rp[data-reply-id]')).map(el => String(el.dataset.replyId)));
  const fresh = r.list.filter(x => x && x.id && !seen.has(String(x.id)));
  if (fresh.length) btn.insertAdjacentHTML('beforebegin', fresh.map(x => CR.reply(x, m, false)).join(''));

  const next = off + r.list.length;
  if (next >= total) btn.remove();
  else {
   btn.dataset.offset = next;
   btn.textContent = `加载更多回复（已显示 ${next}/${total}）`;
   btn.classList.remove('disabled');
  }
 }
 async function moreComments() {
  const btn = document.getElementById('loadMoreCommentsBtn');
  if (!btn || btn.classList.contains('disabled')) return;
  const p = CmtApi.params();
  if (!p) {
   btn.classList.add('disabled');
   btn.textContent = '参数获取失败';
   return;
  }

  const section = document.querySelector('.comments');
  if (!section) return;

  const loaded = parseInt(section.dataset.l1Offset || '', 10);
  const cursor = isNaN(loaded) ?
   document.querySelectorAll('.comments .cm[data-comment-id]').length :
   loaded;

  const seen = new Set(
   Array.from(section.querySelectorAll('.cm[data-comment-id]'))
   .map(el => String(el.dataset.commentId || ''))
   .filter(Boolean)
  );

  btn.classList.add('disabled');
  btn.textContent = '加载中...';
  const r = await CmtApi.l1(p.postId, p.blogId, cursor);
  const list = r.list || [];
  section.dataset.l1Offset = String(cursor + list.length);
  const fresh = list.filter(it => it && it.id && !seen.has(String(it.id)));

  if (fresh.length) {
   // const m = Emo.mk(); // 未使用
   const html = CR.list(fresh, p.postId, p.blogId);
   btn.insertAdjacentHTML('beforebegin', html);
   fillEmptyReplies(p.postId, p.blogId, false);
   fillQuotes();
  }

  const next = cursor + list.length;
  if (r.total != null && next >= Number(r.total)) {
   btn.textContent = '没有更多评论了';
   btn.classList.add('disabled');
  } else if (!fresh.length && !list.length) {
   btn.textContent = '没有更多评论了';
   btn.classList.add('disabled');
  } else {
   btn.textContent = '加载更多评论';
   btn.classList.remove('disabled');
  }
 }

