 /* ===== 引用（pid）工具 ===== */
 let _pidMap = null;

 function resetPidMap() { _pidMap = null; }

 function buildPidMap() {
  const map = new Map();
  document.querySelectorAll('.post-content p').forEach((p, i) => {
   map.set('p_i' + i, p);
   if (p.id) map.set(p.id, p);
  });
  return map;
 }

 function findTarget(pid) {
  if (!pid) return null;
  if (!_pidMap) _pidMap = buildPidMap();
  return _pidMap.get(String(pid)) || null;
 }

 /* 取元素文本（排除 .cm-mark 内标记） */
 function noMark(el) {
  const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  let t = '';
  while (w.nextNode()) {
   const n = w.currentNode;
   const parent = n.parentElement;
   if (parent && parent.closest('.cm-mark')) continue;
   t += n.textContent;
  }
  return t.replace(/\s+/g, ' ').trim();
 }
 const _textCache = new WeakMap();

 function getText(el) {
  if (_textCache.has(el)) return _textCache.get(el);
  const t = noMark(el);
  _textCache.set(el, t);
  return t;
 }
 /* 把引用块的文本填到 .cm-quote */
 function fillQuotes() {
  document.querySelectorAll('.cm-quote[value]').forEach(s => {
   const pid = s.getAttribute('value');
   if (!pid) return;
   const t = findTarget(pid);
   if (pid.indexOf('p_i') === 0) {
    s.textContent = s.getAttribute('data-quote') || '';
    if (t) t.classList.add('is-quoted');
    return;
   }
   if (!t) return;
   t.classList.add('is-quoted');
   s.textContent = getText(t);
  });
 }

 /* ===== 段评弹窗 ===== */
 const Popup = (function() {
  let mask, quoteEl, list, stats, ctx = null, guard;
  let quoteTarget = null;

  function jumpToQuote() {
   if (!quoteTarget) return;
   const t = quoteTarget;
   close();
   setTimeout(() => {
    t.scrollIntoView({ behavior: 'smooth', block: 'center' });
    t.classList.add('is-quoted');
    t.classList.add('is-flash');
    setTimeout(() => t.classList.remove('is-flash'), 2000);
   }, 50);
  }

  function build() {
   if (list) return;
   mask = document.createElement('div');
   mask.className = 'cpop-mask';
   mask.addEventListener('click', e => { if (e.target === mask) close(); });
   mask.addEventListener('touchmove', e => {
    if (e.target.closest('.cpop-list, .cpop-quote')) return;
    e.preventDefault();
   }, { passive: false });

   const box = document.createElement('div');
   box.className = 'cpop';

   const head = document.createElement('div');
   head.className = 'cpop-head';
   const title = document.createElement('h3');
   title.className = 'cpop-title';
   title.textContent = '段落评论';
   const x = document.createElement('button');
   x.className = 'cpop-x';
   x.type = 'button';
   x.innerHTML = '<i class="fa fa-times"></i>';
   x.addEventListener('click', e => { e.stopPropagation();
    close(); });
   head.append(title, x);

   quoteEl = document.createElement('div');
   quoteEl.className = 'cpop-quote';
   quoteEl.addEventListener('click', jumpToQuote);

   list = document.createElement('div');
   list.className = 'cpop-list';
   list.addEventListener('scroll', onScroll);

   stats = document.createElement('div');
   stats.className = 'cpop-stats';

   box.append(head, quoteEl, list, stats);
   mask.appendChild(box);
   document.body.appendChild(mask);
  }

  /* 触底加载下一页 */
  function onScroll() {
   if (!ctx || !ctx.more || ctx.loading) return;
   const { scrollTop, scrollHeight, clientHeight } = list;
   if (scrollTop + clientHeight >= scrollHeight - 50) next();
  }

  function renderStats(s) {
   if (!s) return;
   if (s.count > 0) {
    stats.innerHTML =
     `<span class="cpop-stat cpop-stat--sweet">真甜 ${esc(s.sweet || 0)}</span>` +
     `<span class="cpop-stat cpop-stat--bitter">好虐 ${esc(s.bitter || 0)}</span>` +
     `<span class="cpop-stat cpop-stat--haha">哈哈哈 ${esc(s.haha || 0)}</span>` +
     `<span class="cpop-stat">评论 ${esc(s.count || 0)}</span>`;
   } else {
    stats.innerHTML =
     `<span class="cpop-stat cpop-stat--sweet"><img class="stat-emo" src="${esc(WBI.sweet)}" alt="真甜" onerror="this.style.opacity='0'">真甜 ${esc(s.sweet || 0)}</span>` +
     `<span class="cpop-stat cpop-stat--bitter"><img class="stat-emo" src="${esc(WBI.bitter)}" alt="好虐" onerror="this.style.opacity='0'">好虐 ${esc(s.bitter || 0)}</span>` +
     `<span class="cpop-stat cpop-stat--haha"><img class="stat-emo" src="${esc(WBI.haha)}" alt="哈哈" onerror="this.style.opacity='0'">哈哈哈 ${esc(s.haha || 0)}</span>` +
     `<span class="cpop-stat"><img class="stat-emo" src="${esc(WBI.ping)}" alt="评论" onerror="this.style.opacity='0'">评论 ${esc(s.count || 0)}</span>`;
   }
  }

  async function appendPage(r, first) {
   ctx.off = r.nextOffset;
   ctx.more = r.nextOffset !== -1;

   if (first && !r.list.length) {
    list.style.display = 'none';
    list.innerHTML = '';
    return;
   }
   list.style.display = '';

   const m = Emo.mk();
   r.list.forEach(it => Emo.pick(it, m));
   const html = r.list.map(it => CR.item(it, m, ctx.postId, ctx.blogId, true)).join('');

   if (first) {
    list.innerHTML = html;
    const ind = document.createElement('div');
    ind.className = 'cpop-loading';
    ind.id = 'cpop-load';
    ind.textContent = ctx.more ? '上拉加载更多' : '没有更多了';
    list.appendChild(ind);
   } else {
    const ind = document.getElementById('cpop-load');
    if (ind) {
     ind.insertAdjacentHTML('beforebegin', html);
     ind.textContent = ctx.more ? '上拉加载更多' : '没有更多了';
    } else {
     list.insertAdjacentHTML('beforeend', html);
    }
   }

   fillEmptyReplies(ctx.postId, ctx.blogId, true);
  }

  async function next() {
   if (!ctx || ctx.loading || !ctx.more) return;
   ctx.loading = true;
   const ind = document.getElementById('cpop-load');
   if (ind) ind.textContent = '加载中...';
   const page = await CmtApi.para(ctx.postId, ctx.blogId, ctx.pid, ctx.off);
   if (!ctx) return; // 重检
   if (!page.list.length) ctx.more = false;
   await appendPage(page, false);
   ctx.loading = false;
  }

  function bindQuote(pid) {
   quoteTarget = findTarget(pid);
   if (quoteTarget) {
    quoteEl.textContent = getText(quoteTarget);
    quoteEl.style.display = '';
   } else {
    quoteEl.textContent = '';
    quoteEl.style.display = 'none';
   }
  }

  async function open(pid, st) {
   build();
   mask.classList.add('open');
   lockBodyScroll();
   list.scrollTop = 0;
   const noText = st && !st.count;
   list.style.display = noText ? 'none' : '';
   list.innerHTML = noText ? '' : '<div class="cpop-loading">加载中...</div>'; 

   const postId = val('postId');
   const blogId = val('blogId');
   if (!postId || !blogId || !pid) {
    quoteEl.style.display = 'none';
    list.style.display = 'none';
    stats.innerHTML = '';
    Host.toast('参数缺失');
    close();
    return;
   }

   bindQuote(pid);
   ctx = { pid, postId, blogId, off: 0, more: false, loading: false };
   renderStats(st);

   await new Promise(r => requestAnimationFrame(r));
   const first = await CmtApi.para(postId, blogId, pid, 0);
   await appendPage(first, true);
  }

  function close() {
   if (mask) mask.classList.remove('open');
   unlockBodyScroll();
   if (quoteEl) { quoteEl.textContent = '';
    quoteEl.style.display = 'none'; }
   if (list) { list.innerHTML = '';
    list.scrollTop = 0;
    list.style.display = ''; }
   if (stats) stats.innerHTML = '';
   quoteTarget = null;
   ctx = null;
  }

  return { open, close };
 })();

