   const sd = shared();
   switch (kind) {
    case 'export-ext':
     e.stopPropagation();
     exportTxtClick();
     return;   
    case 'article-add':
     e.stopPropagation();
     addArticle(sd.article.title, sd.article.url);
     return;
    case 'follow':
     e.stopPropagation();
     addAuthor(sd.author.blogId, sd.author.name, sd.author.avatar);
     return;
    case 'tts':
     e.stopPropagation(); e.preventDefault();
     ttsPlay(); return;
    case 'collection-trigger':
     e.stopPropagation();
     if (sd.author.blogId) ColDialog.open(sd.author.blogId);
     return;
    case 'collection-info':
     e.stopPropagation(); PostNav.openToc(); return;
    case 'collection-import':
     e.preventDefault(); e.stopPropagation();
     if (!sd.collection.name || !sd.collection.id) { Host.toast('合集无法添加'); return; }
     addCol(sd.collection.name, sd.collection.id);
     return;
    case 'collection-open': {
      e.preventDefault();e.stopPropagation();
      if (!sd.collection.name || !sd.collection.id) { Host.toast('合集无法打开'); return; }
      const o = {};
      o['📖 ' + sd.collection.name] = `${API.COLL}?product=lofter-android-8.0.2&method=getCollectionDetail&offset={{(page-1)*45}}&limit=45&collectionid=${encodeURIComponent(sd.collection.id)}`;
      Host.open('sort', JSON.stringify(o));
      return;
     }
   }
   return;
  }

  const link = e.target.closest('a[href]');
  if (!link) return;
  const h = link.getAttribute('href');
  if (!h || !/lofter\.com/.test(h)) return;
  try {
   if (routeLink(h, link.getAttribute('title'))) {
    e.preventDefault(); e.stopPropagation();
   }
  } catch (err) { Host.toast('链接处理失败'); }

 }, true);

