 function importCol(n, id, bid) {
  const body = `targetblogid=${encodeURIComponent(bid)}&method=getCollectionSimple&offset=0&limit=800&blogid=${encodeURIComponent(bid)}&collectionid=${encodeURIComponent(id)}&order=1`;
  const src = `${API.COLL}?product=lofter-android-7.4.4,` + JSON.stringify({ method: 'POST', body });
