function ttsVideoPlay() {
  const p = val('postId'), b = val('blogId'), c = val('collection-id');
  if (!p || !b || !c) return Host.toast('非合集');
  try {
    const info = JSON.parse(Host.ajax(`${API.AUDIO}info.json?postId=${p}&blogId=${b}&collectionId=${c}`)); 
    if (info.code) return Host.toast(`code=${info.code} ${info.msg || ''}`);
    const it = (info.data?.audioPost?.toneInfos || []).find(t => t && t.unlocked); 
    if (!it) return Host.toast('无音轨');
    Host.openVideoPlayer(it.audioUrl, info.data.post.title || 'LOFTER 朗读', true);
  } catch (e) { Host.toast(e.message); }
}

/* ===== LOFTER 听书 ===== */
var TTS_TTL = 6 * 36e5;
var _ttsPanel, _ttsAudio, _ttsActive, _ttsCues = [], 
 _ttsTimer, _ttsEnded, _ttsPid, _ttsFill, _ttsTime,
 _ttsHls, _ttsDocBound, _ttsLastSave;

function ttsPlay() {
 var p = val('postId'), b = val('blogId'), c = val('collection-id'); 
 if (!p || !b || !c) return Host.toast('非合集'); 
 if (_ttsPanel) return;

 // 命中缓存 
 var cached;
 try { cached = JSON.parse(sessionStorage.getItem('ttsAuto') || 'null'); } catch (e) {}
 if (cached && cached.url && String(cached.pid) === String(p)) {
  try { sessionStorage.removeItem('ttsAuto'); } catch (e) {}
  _ttsPid = String(p); build(cached.url, cached.sub); return;
 }
 try { sessionStorage.removeItem('ttsAuto'); } catch (e) {}

 // 无缓存：拉接口 
 var json;
 try { json = JSON.parse(Host.ajax(`${API.AUDIO}info.json?postId=${p}&blogId=${b}&collectionId=${c}`)); }
 catch (e) { return Host.toast('请求失败'); }
 if (json.code) return Host.toast('code=' + json.code);
 var post = json.data.post, info = (json.data.audioPost.toneInfos || []).find(function (t) { return t && t.unlocked; }); 
 if (!post || !info) return Host.toast('无音轨'); 
 _ttsPid = String(post.postId); build(info.audioUrl, info.subtitleUrl);
}

function build(audioUrl, subtitleUrl) {
 var seekAt = 0;
 try { var prog = JSON.parse(localStorage.getItem('loftts') || 'null');
  if (prog && String(prog.pid) === String(_ttsPid) && Date.now() - (prog.ts || 0) <= TTS_TTL && prog.time > 20 && (!prog.dur || prog.time < prog.dur - 15)) { seekAt = prog.time; 
   Host.toast('上次听到 ' + (prog.time / 60 | 0) + ':' + ('0' + (prog.time % 60 | 0)).slice(-2) ); } 
 } catch (e) {}

 _ttsPanel = document.createElement('div');
 _ttsPanel.className = 'tts-cap';
 _ttsPanel.innerHTML = '<button class="c-pr"><i class="fa fa-skip-previous"></i></button><button class="c-pp"><i class="fa fa-pause-circle"></i></button><button class="c-nx"><i class="fa fa-skip-next"></i></button><div class="c-p"><i></i></div><span class="c-m">0:00</span><button class="c-x"><i class="fa fa-times"></i></button>';
 document.body.appendChild(_ttsPanel);
 // 折叠收纳
_ttsPanel.addEventListener('click', function () {
 if (_ttsPanel.classList.contains('collapsed')) _ttsPanel.classList.remove('collapsed');}, true); 
if (!_ttsDocBound) {_ttsDocBound = 1;
 document.addEventListener('click', function (e) {
  if (_ttsPanel && !_ttsPanel.contains(e.target)) _ttsPanel.classList.add('collapsed');
 }, true);}

 _ttsAudio = document.createElement('audio');
 _ttsAudio.className = 'tts-v';
 _ttsAudio.setAttribute('playsinline', '');
 document.body.appendChild(_ttsAudio);
 // if ('mediaSession' in navigator) navigator.mediaSession.metadata = new MediaMetadata({ title: val('article-title'), artist: val('author-name') }); 
 // document.body.style.paddingTop = '60px';
 var playBtn = _ttsPanel.querySelector('.c-pp');
 var progressBar = _ttsPanel.querySelector('.c-p');
 _ttsFill = _ttsPanel.querySelector('.c-p i');
 _ttsTime = _ttsPanel.querySelector('.c-m');
 ttsLoad(audioUrl, subtitleUrl, seekAt, true);
 playBtn.onclick = function (e) { e.stopPropagation(); _ttsAudio.paused ? _ttsAudio.play() : _ttsAudio.pause(); }; 
 _ttsPanel.querySelector('.c-pr').onclick = function (e) { e.stopPropagation(); /*ttsJump('pre');*/ ttsSeekCue(-1); }; 
 _ttsPanel.querySelector('.c-nx').onclick = function (e) { e.stopPropagation(); /*ttsJump('next');*/ ttsSeekCue(1); }; 
 _ttsPanel.querySelector('.c-x').onclick = function (e) { e.stopPropagation(); ttsStop(); }; 
 _ttsAudio.onplay  = function () { playBtn.innerHTML = '<i class="fa fa-pause-circle"></i>'; if (!_ttsTimer) _ttsTimer = setInterval(ttsSync, 250); };
 _ttsAudio.onpause = function () { playBtn.innerHTML = '<i class="fa fa-play-circle"></i>'; if (_ttsTimer) { clearInterval(_ttsTimer); _ttsTimer = null; } };
 _ttsAudio.onended = function () { if (!_ttsEnded) { _ttsEnded = true; ttsJump('next'); } }; 
 progressBar.onclick = function (e) {
  var rect = progressBar.getBoundingClientRect();
  if (_ttsAudio.duration) {
   var ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
   _ttsAudio.currentTime = ratio * _ttsAudio.duration;
   if (_ttsAudio.paused) _ttsAudio.play().catch(function(){});
 } };
 _ttsEnded = false; // _ttsTimer = setInterval(ttsSync, 250); 
}

function ttsLoad(audioUrl, subtitleUrl, seekTo, autoPlay) {
 if (_ttsHls) { try { _ttsHls.destroy(); } catch (e) {} _ttsHls = null; }
 if (_ttsActive) { _ttsActive.classList.remove('tts-hl'); _ttsActive = null; }
 _ttsCues = [];
 if (subtitleUrl) { try { _ttsCues = ttsSub(String(Host.ajax(subtitleUrl) || '')); } catch (e) { _ttsCues = []; } }
 var useHls = window.Hls && /\.m3u8(\?|$)/i.test(audioUrl); 
 var startAt = seekTo || 0, autoplay = autoPlay !== false; 
 if (useHls) { _ttsHls = new Hls();
  _ttsHls.loadSource(audioUrl); _ttsHls.attachMedia(_ttsAudio); 
  _ttsHls.on(Hls.Events.MANIFEST_PARSED, function () {
   if (startAt > 0) { setTimeout(function () { try {_ttsAudio.currentTime = startAt; } catch (e) {} }, 250); } 
   if (autoplay) _ttsAudio.play().catch(function(){}); }); 
 } else { _ttsAudio.src = audioUrl; _ttsAudio.onloadedmetadata = function () { 
   if (startAt > 0) { try { _ttsAudio.currentTime = startAt; } catch (e) {} } 
   if (autoplay) _ttsAudio.play().catch(function(){}); }; 
   _ttsAudio.load(); 
 }
}

function ttsSync() {
 if (!_ttsAudio) return;
 var time = _ttsAudio.currentTime || 0, duration = _ttsAudio.duration || 0;
 if (duration) {
  _ttsFill.style.width = time / duration * 100 + '%';
  _ttsTime.textContent = (time / 60 | 0) + ':' + ('0' + (time % 60 | 0)).slice(-2); 
  //if (!_ttsEnded && time >= duration - 0.8) { _ttsEnded = true; ttsJump('next'); return; }
  if (!_ttsLastSave || time - _ttsLastSave >= 5) { _ttsLastSave = time;
   try { localStorage.setItem('loftts', JSON.stringify({ pid: _ttsPid || '', time: time, dur: duration, ts: Date.now() })); } catch (e) {} 
  }
 }
 var current;
 for (var i = 0; i < _ttsCues.length; i++)
  if (time >= _ttsCues[i].start && time <= _ttsCues[i].end) { current = _ttsCues[i]; break; }
 var paragraph = current && current.paragraph;
 if (paragraph === _ttsActive) return;
 if (_ttsActive) _ttsActive.classList.remove('tts-hl');
 if (paragraph) {
  paragraph.classList.add('tts-hl');
  var rect = paragraph.getBoundingClientRect();
  if (rect.top < 100 || rect.bottom > innerHeight - 100)
   scrollTo({ top: pageYOffset + rect.top - innerHeight * 0.3, behavior: 'smooth' }); 
 }
 _ttsActive = paragraph;
}

function ttsSub(raw) {
 var text = String(raw || '').trim();
 if (!text) return [];
 var list = [];
 if (text.charAt(0) === '{' || text.charAt(0) === '[') {
  try {
   var json = JSON.parse(text);
   var arr = Array.isArray(json) ? json : (json.list || json.cues || json.subtitles || json.data || []); 
   list = arr.map(function (item) {
    if (item.time_begin != null)
     return { start: +item.time_begin / 1e3, end: +item.time_end / 1e3, text: String(item.text || '').trim() }; 
    var a = item.startTime != null ? item.startTime : (item.start != null ? item.start : (item.from != null ? item.from : (item.st != null ? item.st : 0))); 
    var b = item.endTime != null ? item.endTime : (item.end != null ? item.end : (item.to != null ? item.to : (item.et != null ? item.et : 0))); 
    var k = (+a > 1e4 || +b > 1e4) ? 1e3 : 1;
    return { start: +a / k, end: +b / k, text: String(item.text || item.content || '').trim() };  
   }).filter(function (item) { return item.text; });
  } catch (e) {}
 } else {
  var current, lines = text.split(/\r?\n/);
  for (var i = 0; i < lines.length; i++) {
   var m = lines[i].match(/^(\d+):(\d+):(\d+)[.,](\d+)\s*-->\s*(\d+):(\d+):(\d+)[.,](\d+)/); 
   if (m) {
    if (current) list.push(current);
    current = { start: +m[1] * 3600 + +m[2] * 60 + +m[3] + +m[4] / 1e3,
      end:   +m[5] * 3600 + +m[6] * 60 + +m[7] + +m[8] / 1e3, text: '' };
   } else if (current && lines[i].trim() && !/^\d+$/.test(lines[i].trim()) && !/^WEBVTT/.test(lines[i])) { 
    current.text += (current.text ? ' ' : '') + lines[i].trim();
   }
  }
  if (current) list.push(current);
 }
 if (!list.length) return list;
 var paragraphs = Array.from(document.querySelectorAll('.post-content p'))
  .filter(function (p) { return (p.textContent || '').trim(); });
 if (!paragraphs.length) return list;
 var normalize = function (s) { return (s || '').replace(/[\s\p{P}\p{S}ァ-ヶぁ-ん]/gu, ''); }; 
 var cursor = 0;

var texts = paragraphs.map(function (p) { return normalize(p.textContent); });
list.forEach(function (cue) {
 var target = normalize(cue.text), tlen = target.length;
 if (tlen < 1) return;
 var best = -1, bestScore = 0;
 for (var pass = 0; pass < 2 && best < 0; pass++) {
  var from = pass === 0 ? cursor : 0, to = pass === 0 ? texts.length : cursor;
  for (var i = from; i < to; i++) {
   var source = texts[i];
   if (!source) continue;
   if (source.indexOf(target) >= 0) {
    var score = tlen / source.length;
    if (score > bestScore) { bestScore = score; best = i; }
    if (score === 1) break;
    continue; }
   if (tlen < 10) continue;
   var len = Math.min(20, source.length, tlen), hits = 0;
   for (var j = 0; j < len; j++) if (source.charAt(j) === target.charAt(j)) hits++;
   var ratio = hits / tlen;
   if (ratio > bestScore && ratio > 0.5) { bestScore = ratio; best = i; }
  }
 }
 if (best >= 0) { cursor = best + 1; cue.paragraph = paragraphs[best]; }
});

 return list;
}

function ttsStop() {
 if (_ttsTimer) clearInterval(_ttsTimer);
 if (_ttsHls) { try { _ttsHls.destroy(); } catch (e) {} _ttsHls = null; }
 if (_ttsAudio) { try { _ttsAudio.pause(); } catch (e) {} _ttsAudio.remove(); } 
 if (_ttsPanel) _ttsPanel.remove();
 if (_ttsActive) _ttsActive.classList.remove('tts-hl');
 _ttsPid = _ttsPanel = _ttsAudio = _ttsActive = _ttsTimer = _ttsFill = _ttsTime = null; 
 _ttsCues = []; _ttsEnded = false; _ttsLastSave = 0;
 document.body.style.paddingTop = '';
}

// 切播 dir: -1/+1 = 上/下一段
function ttsSeekCue(dir) {
 if (!_ttsAudio || !_ttsCues.length) return;
 var t = _ttsAudio.currentTime, i = 0;
 while (i < _ttsCues.length - 1 && t >= _ttsCues[i].end) i++;
 if (dir < 0) {
  _ttsAudio.currentTime = (i === 0 || t - _ttsCues[i].start > 1)
   ? _ttsCues[i].start
   : _ttsCues[i - 1].start;
 } else {
  _ttsAudio.currentTime = (i < _ttsCues.length - 1)
   ? _ttsCues[i + 1].start
   : (_ttsAudio.duration || t);
 }
 ttsSync();
}

function ttsJump(dir) {
 var p = _ttsPid || val('postId'), b = val('blogId'), c = val('collection-id');
 if (!p || !b || !c) return;
 var json;
 try { json = JSON.parse(Host.ajax(`${API.AUDIO}${dir}.json?postId=${p}&blogId=${b}&collectionId=${c}`)); }
 catch (e) { return; }
 var data = json.data || {}, post = data.post;
 var info = (data.audioPost && data.audioPost.toneInfos || []).find(function (t) { return t && t.unlocked; }); 
 if (!post || String(post.postId) === String(p)) return Host.toast(dir === 'pre' ? '已是首篇' : '已是末篇'); 
 if (!info) return Host.toast('无音轨'); 
 try {
  sessionStorage.setItem('ttsAuto', JSON.stringify({
   url: info.audioUrl, sub: info.subtitleUrl, pid: String(post.postId)
  }));
 } catch (e) {}
 var domain = (data.blogInfo && data.blogInfo.blogName) || 'www';
 var targetBlogId = post.blogId || b;
 var body = `targetblogid=${targetBlogId}&blogdomain=${domain}.lofter.com&postid=${post.postId}`; 
 var rssUrl = `${API.POST}?product=lofter-android-8.3.64,` +
  JSON.stringify({ method: 'POST', 'accept-encoding': 'gzip, deflate', body });
 Host.toast('即将播放...\n' + (post.title || post.postId));
 Host.open('rss', rssUrl, post.title || '');
}

