 try { if (!sessionStorage.getItem('ttsAuto')) return; } catch (e) { return; }
 if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', function () { setTimeout(ttsPlay, 300); }); } 
 else { setTimeout(ttsPlay, 300); }
})();

 /* ===== 长按：标签 / 合集 / 作者 / 列表 / 听书 ===== */
 (function() {
  let timer = null, target = null, fired = false,
       startX = 0, startY = 0;
  function clear() { if (timer) { clearTimeout(timer);
    timer = null; } target = null; }

  document.addEventListener('touchstart', e => {
   const t = e.target.closest('.post-tags__item, .post-col__info, .post-author__name, .cb-card, .post-nav__item, .btn--tts'); 
   if (!t) return;
   target = t; fired = false;
   startX = e.touches[0].clientX;
   startY = e.touches[0].clientY;
   timer = setTimeout(() => {
    timer = null; fired = true;
    if (t.classList.contains('post-tags__item')) {
     addTag(t.textContent.trim());
    } else if (t.classList.contains('post-col__info')) {
     const c = shared().collection;
     if (c.name && c.id && c.blogId) importCol(c.name, c.id, c.blogId);
    } else if (t.classList.contains('post-nav__item')) {
     if (t.classList.contains('post-nav__item--disabled')) return;
     PostNav.openToc();
    } else if (t.classList.contains('cb-card')) {
     addCol(t.dataset.collectionName, t.dataset.collectionId);
    } else if (t.classList.contains('btn--tts')) {
     ttsVideoPlay();
    } else {
     const a = shared().author;
     if (a && a.blogId) AuthorDialog.open(a.blogId);
     else Host.toast('作者信息缺失');
    }
    Host.vibrate(VIBRATE_MS);
   }, LONG_PRESS_MS);
  }, { passive: true });

  document.addEventListener('touchend', e => {
   if (fired) {
    /*e.preventDefault(); e.stopPropagation();*/
    fired = false;
   }
   clear();
  });

  document.addEventListener('touchmove', e => {
   if (!timer || !target) return;
   const dx = e.touches[0].clientX - startX;
   const dy = e.touches[0].clientY - startY;
   if (Math.abs(dx) > LONG_PRESS_SLOP || Math.abs(dy) > LONG_PRESS_SLOP) clear();
  }, { passive: true });

  document.addEventListener('touchcancel', clear);
 })();

 /* ===== 上/下一篇（仅合集） ===== */
 const PostNav = (function() {
  const LIMIT = 1e3, LEN = 40, PAGE = 45; // 目录总数 / 标题长度 / 存储 上限
  const NAV_TTL = 28*21600; // 7d (0不过期)

  const clip = s => {
   s = String(s || '').replace(/<[^<>]*>/g, '').replace(/\s+/g, ' ').trim() || '无题';
   const a = Array.from(s); return a.length > LEN ? a.slice(0, LEN).join('') + '…' : s;
  };
  const dom = () => (String(val('article-url')).match(/^https?:\/\/([^.]+)\.lofter\.com/i) || [, ''])[1];
  const hex = (b, p) => { try { return `${BigInt(b).toString(16)}_${BigInt(p).toString(16)}`; } catch (e) { return ''; } };

  /* 精简结构：[{id, blogId, title}] */
  function slimNav(list) { const out = [];
   for (let i = 0; i < list.length; i++) { const x = list[i];
    const p = x && x.post ? x.post : x;
    const clean = s => String(s).replace(/<[^<>]*>/g, '').replace(/\s+/g, ' ').trim();
    if (!p || p.id == null || p.blogId == null) continue;
    out.push({ id: String(p.id), blogId: String(p.blogId), title: clean(p.title || p.digest || '') });
   } return out;
  }

  /* 合并去重：items 为 [{id, blogId, title}] */
  const merge = (list, seen, items) => {
   for (const it of items) { const k = it.id + ':' + it.blogId;
    if (!seen.has(k)) { seen.add(k); list.push(it); }
   }
  };
  const fetchPage = async (colId, off) => {
   const d = await ajaxJson(`${API.COLL}?product=lofter-android-8.0.2&method=getCollectionDetail&offset=${off}&limit=${PAGE}&order=1&collectionid=${colId}`);
   const resp = (d && d.response) || {};
   return {
    items: slimNav((resp.items || resp.posts) || []),
    postCount: Number((resp.collection && resp.collection.postCount) || 0)
   };
  };

   async function fetch_(colId) {
   // localStorage.clear(); Host.toast('测试用，清空缓存！'); 
   const key = 'lofnav:' + colId; const now = Date.now(); let cache = null;
   /* 读缓存（有效期内）*/
   try { const obj = JSON.parse(localStorage.getItem(key) || 'null');
     if (obj?.t && now - obj.t < NAV_TTL * 1e3 && obj.d?.length) cache = obj;
   } catch (e) {}
   if (cache && now - (cache.lt || cache.t) < 36e5) return cache.d.slice(); 

   /* 分批获取合集目录 */
   const list = cache ? cache.d.slice() : [];
   const seen = new Set(list.map(x => x.id + ':' + x.blogId));
   let lastOff, dirty = false;

   if (cache) { /* 更新 */
    lastOff = cache.lastOff ?? 0;
    for (let off = lastOff; off < LIMIT; off += PAGE) {
     const { items } = await fetchPage(colId, off);
     if (!items.length) break; const before = list.length;
     merge(list, seen, items); lastOff = off;
     if (list.length === before) break; dirty = true; 
    }
   } else { /* 无缓存 */
    const first = await fetchPage(colId, 0);
    const pages = Math.max(0, Math.min(Math.ceil(first.postCount / PAGE), Math.ceil(LIMIT / PAGE))); 
    const startOff = Math.max(0, (Math.ceil(first.postCount / PAGE) - pages) * PAGE);
    lastOff = -PAGE; dirty = true;
    for (let i = 0; i < pages; i++) { const off = startOff + i * PAGE;
     const { items } = off === 0 ? first : await fetchPage(colId, off);
     merge(list, seen, items); lastOff = off;
    }
   }
   if (dirty && list.length) {
    try { localStorage.setItem(key, JSON.stringify({ t: Date.now(), d: list, lastOff }));
     for (const k of Object.keys(localStorage)) {
      if (!k.startsWith('lofnav:') || k === key) continue;
      const t = Number((localStorage.getItem(k) || '').match(/"t":(\d+)/)?.[1]) || 0;
      if (!t || now - t >= NAV_TTL * 1e3) localStorage.removeItem(k);
     }
    } catch (e) { Host.toast('目录缓存出错'); }
   }
   return list;
  }

  const row = (x, d, label, empty) => {
   if (!x || !x.id || !x.blogId) return `<span class="post-nav__item post-nav__item--disabled"><span class="post-nav__label">${label}</span><span class="post-nav__title">${empty}</span></span>`;
   const h = hex(x.blogId, x.id), t = clip(x.title); if (!h || !d) return '';
   return `<a class="post-nav__item" href="https://${d}.lofter.com/post/${h}" title="${esc(t)}"><span class="post-nav__label">${label}</span><span class="post-nav__title">${t}</span></a>`;
  };

  async function load() {
   const cid = val('collection-id'), pid = val('postId'), d = dom();
   const anchor = document.querySelector('.comments') || document.querySelector('.post-footer'); 
   if (!cid || !pid || !d || !anchor) return; // 非合集文章直接退出

   let all;
   try { all = await fetch_(cid); } catch (e) { return; }
   if (!all.length) return;

   const i = all.findIndex(x => x && String(x.id) === String(pid));
   if (i === -1) return;

   const html = row(all[i - 1], d, '← 上一篇', '已是首篇') +
    row(all[i + 1], d, '下一篇 →', '已是末篇');
   if (!html.includes('<a ')) return;

   document.querySelectorAll('.post-nav').forEach(n => n.remove());
   const box = document.createElement('nav');
   box.className = 'post-nav';
   box.innerHTML = html;
   anchor.parentNode.insertBefore(box, anchor);
  }

  /* ===== 目录抽屉 ===== */
  let tocMask, tocList, tocTitle, tocMeta;

  function tocBuild() {
   if (tocMask) return;
   tocMask = document.createElement('div');
   tocMask.className = 'toc-mask';
   tocMask.innerHTML = `
  <div class="toc">
   <div class="toc-head">
    <div class="toc-head__main">
     <h3 class="toc-title"></h3>
     <span class="toc-meta"></span>
    </div>
    <button class="toc-x" type="button"><i class="fa fa-times"></i></button>
   </div>
   <div class="toc-list"></div>
  </div>`;
   tocTitle = tocMask.querySelector('.toc-title');
   tocMeta = tocMask.querySelector('.toc-meta');
   tocList = tocMask.querySelector('.toc-list');
   tocMask.addEventListener('click', e => { if (e.target === tocMask) tocClose(); });
   tocMask.addEventListener('touchmove', e => {
    if (!e.target.closest('.toc') && e.cancelable) e.preventDefault(); 
   }, { passive: false });
   tocMask.querySelector('.toc-x').addEventListener('click', tocClose); 
   document.body.appendChild(tocMask);
  }

  function tocClose() {
   if (tocMask) tocMask.classList.remove('open');
   unlockBodyScroll();
  }

  /* 渲染目录 */
  function renderToc(all) { const curId = String(val('postId')), d = dom();
   const cur = all.findIndex(x => String(x.id) === curId);
   tocMeta.textContent = (cur >= 0 ? (cur + 1) + ' / ' : '') + all.length + ' 篇';
   tocList.innerHTML = all.map((x, i) => { const h = hex(x.blogId, x.id);
    if (!h || !d) return '';
    const t = clip(x.title); const a = String(x.id) === curId ? ' active' : '';
    return `<a class="toc-item${a}" href="https://${d}.lofter.com/post/${h}" title="${esc(t)}"><span class="toc-idx">${i + 1}</span><span class="toc-name">${t}</span></a>`; }).join(''); 
   const curEl = tocList.querySelector('.toc-item.active');
   if (curEl) setTimeout(() => curEl.scrollIntoView({ block: 'center' }), 60);
  }

  async function openToc() {
   const cid = val('collection-id');
   if (!cid) return Host.toast('非合集作品'); tocBuild();
   tocTitle.textContent = val('collection-name') || '目录';
   tocMask.classList.add('open'); lockBodyScroll();
   /* 先渲染缓存 */
   let cached = null;
   try { const obj = JSON.parse(localStorage.getItem('lofnav:' + cid) || 'null');
    if (obj?.d?.length) cached = obj.d;
   } catch (e) {}
   if (cached) renderToc(cached);
   else tocList.innerHTML = '<div class="toc-status">加载中...</div>';
   await new Promise(r => requestAnimationFrame(r));
   try { const all = await fetch_(cid);
    if (all.length) { if (!cached || all.length !== cached.length) renderToc(all); }
    else if (!cached) tocList.innerHTML = '<div class="toc-status">暂无目录</div>';
   } catch (e) { 
    if (!cached) tocList.innerHTML = '<div class="toc-status">加载失败</div>'; 
   }
  }

  return { load, openToc };
 })();

 /* ===== 阅读历史（延时写入） ===== */
 function recordHistory() {
  try {
   var url = val('article-url');
   if (!url) return;
   var title = val('article-title') || (`『${val('author-name')}』的作品`);
   var cid = val('collection-id');
   var cname = val('collection-name');
   var list = [];
   try {
    var raw = source.get('lofHistory');
    if (raw && raw.trim()) {
     var parsed = JSON.parse(raw);
     if (Array.isArray(parsed)) list = parsed.filter(function(x) { return x && x.url; });
    }
   } catch (e) {}
   var rec = { title: title, url: url, time: Date.now() };
   if (cid) { rec.collectionId = cid;
    rec.collectionName = cname; }
   var seen = {};
   list = list.filter(function(x) {
    if (seen[x.url]) return false;
    if (String(x.url) === url) return false;
    if (cid && String(x.collectionId || '') === cid) return false; // 合集去重复
    seen[x.url] = 1;
    return true;
   });
   list.unshift(rec);
   if (list.length > 800) list.length = 800;
   source.put('lofHistory', JSON.stringify(list));
  } catch (e) {}
 }

 /* ===== 初始化与生命周期 ===== */
 function boot() {
  Viewer.scan();
  loadCommentCounts();
  const idle = window.requestIdleCallback || (fn => setTimeout(fn, 200));
  idle(() => loadInitialComments(), { timeout: 1000 });
  idle(() => fillEmptyReplies(val('postId'), val('blogId'), false), { timeout: 1500 });
  idle(() => PostNav.load(), { timeout: 2000 });
  idle(() => fillQuotes(), { timeout: 3000 });
  idle(() => recordHistory(), { timeout: 3500 });
 }

 if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot);
 } else {
  boot();
 }

 /* SPA 场景：DOM 变动后去抖重扫 */
 if (typeof MutationObserver !== 'undefined') {
  let _moTimer = null;
  const mo = new MutationObserver(() => {
   if (_moTimer) return;
   _moTimer = setTimeout(() => {
    _moTimer = null;
    resetPidMap();
    _sharedSig = '';
    _sharedCache = null;
    Viewer.scan();
    initMoreComments();
    fillEmptyReplies(val('postId'), val('blogId'), false);
    fillQuotes();
   }, 300);
  });
  /*mo.observe(document.body, { childList:true, subtree:true });*/
  mo.observe(document.documentElement, { childList: true, subtree: true });
 }

})();

