// ===== 登录信息更新 =====
function login() {
 updateInfo();
 // 如需清除登录信息可取消注释
 // source.removeLoginInfo();
}

function loginWeb() {
 var head = {}
 head["User-Agent"] = "Dalvik/2.1.0";
 var header = JSON.stringify(head);
 java.startBrowser('https://www.lofter.com/front/account/login?theme=lofter#login,{"headers": ' + header + '}','')
}

// ===== 通用变量读写 =====
function getVarConfig() {
 try {
  var raw = (typeof source !== 'undefined' && source.getVariable) ? source.getVariable() || '' : ''; 
  return raw.trim() ? JSON.parse(raw) : {};
 } catch (e) {
  java.toast('变量格式错误，已重置');
  return {};
 }
}

function saveVarConfig(config) {
 if (!source || !source.setVariable) {
  java.toast('变量不可用');
  return false;
 }
 source.setVariable(JSON.stringify(config));
 return true;
}

function updateInfo() {
 try {
  var info = source && source.getLoginInfoMap ? source.getLoginInfoMap() : null;
  var config = getVarConfig();
  var changed = false;
  if (!config.lofterAuth) config.lofterAuth = '';
  var fieldConfigs = [
  { name: 'type', mapping: { '📃 文字': '1', '🎨 图片': '2', '📺 视频': '4', '🔺 全部': '' }, default: '' },
  { name: 'find', mapping: { '🏷️ 标签': '1', '📖 合集': '2', '👤 作者': '3', '🔺 全部': '' }, default: '' },
  { name: 'comments', mapping: { '最新评论': '0', '热门评论': '1', '精简评论': '', '关闭评论': '-1' }, default: '' }
];
  fieldConfigs.forEach(function (fc) {
   var raw = info ? info.get(fc.name) : null;
   var value = mapValue(raw, fc.mapping, fc.default);
   if (config[fc.name] !== value) {
    config[fc.name] = value;
    changed = true;
   }
  });

  if (changed) saveVarConfig(config);
 } catch (e) {}
}

function mapValue(raw, mapping, defaultVal) {
 if (raw == null) return defaultVal;
 return mapping.hasOwnProperty(raw) ? mapping[raw] : defaultVal;
}

// ===== 标签 / 合集管理 =====
function tryAddTo(key, value, existsFn) {
 var config = getVarConfig();
 if (!Array.isArray(config[key])) config[key] = [];
 if (config[key].some(existsFn)) return false;
 config[key].push(value);
 return saveVarConfig(config);
}

function tryDelTo(key, matchFn, notFoundMsg) {
 var config = getVarConfig();
 if (!Array.isArray(config[key]) || config[key].length === 0) {
  java.toast(notFoundMsg || '没有可删除的项目');
  return false;
 }
 var idx = config[key].findIndex(matchFn);
 if (idx === -1) {
  java.toast(notFoundMsg || '未找到匹配项');
  return false;
 }
 config[key].splice(idx, 1);
 return saveVarConfig(config);
}

function addTag() {
 let info = source.getLoginInfoMap();
 try {
  if ("标签名称" in result) info = result;
 } catch (e) {}

 let tag = String(info.get("标签名称")).trim();
 if (!tag) { java.toast("请输入标签名称"); return; }

 if (tryAddTo('tags', tag, function (t) { return t === tag; })) {
  java.toast('标签「' + tag + '」已添加');
 } else {
  java.toast('标签「' + tag + '」已存在');
 }
}

function addCollection() {
 let info = source.getLoginInfoMap();
 try {
  if ("合集名称" in result && "ID" in result) info = result;
 } catch (e) {}

 let name = String(info.get("合集名称")).trim();
 let id = String(info.get("ID")).trim();

 if (!name || !id) {
  java.toast("请输入合集名称和ID");
  return;
 }
 if (!/^\d+$/.test(id)) {
  java.toast("合集ID必须为数字");
  return;
 }

 if (tryAddTo('collections', { name: name, id: id }, function (item) {
  return item.id === id;
 })) {
  java.toast('合集「' + name + '」已添加');
 } else {
  java.toast('合集「' + name + '」已存在');
 }
}

// ===== 登录令牌处理 =====
function getAuthFromCookie() {
 try {
  var c = cookie.getCookie('https://www.lofter.com');
  var m = String(c).match(/(?:^|;\s*)LOFTER-PHONE-LOGIN-AUTH=([^;]+)/i);
  if (m && m[1]) return m[1].trim();
 } catch (e) {
  java.toast('登录数据读取失败: ' + (e.message || e));
 }
 return '';
}

function addAuth() {
 var info = source.getLoginInfoMap();
 var token = '';
 // 优先从登录信息中获取令牌
 try {
  if (info && info.get('登录令牌')) {
   token = String(info.get('登录令牌')).trim();
  }
 } catch (e) {}
 // 尝试从 Cookie 获取
 if (!token) {
  token = getAuthFromCookie();
 }
 // 获取当前配置中的令牌
 var config = getVarConfig();
 var oldToken = config.lofterAuth;

 if (token) {
  config.lofterAuth = token;
  saveVarConfig(config);
  java.toast('登录令牌已保存');
 } else {
  if (oldToken && oldToken !== '') {
   java.toast('登录令牌获取失败，保留原令牌');
  } else {
   config.lofterAuth = '';
   saveVarConfig(config);
   java.toast('已保存空令牌');
  }
 }
}

