@js: //java.log(result);
/* ===== 日志 ===== */
var Log = {
  _on: true,
  _out(tag, msg) {
    if (!Log._on) return;
    try { java.log(`[lofter][${tag}] ${msg}`); } catch (e) {}
  },
  debug(m) { Log._out('[DEBUG]', m); },
  warn(m) { Log._out('[WARN]', m); },
  error(m) { Log._out('[ERROR]', m); }
};

/* ===== 环境初始化 ===== */
function initEnvironment() {
  var tipMsg = "{{$.meta.msg}}";
  if (tipMsg) java.toast(tipMsg);
  try {
    var c = String(cookie.getCookie("https://www.lofter.com"));
    var m = c.match(/(?:^|;\s*)(LOFTER-[^-]+-LOGIN-AUTH)=([^;]+)/);
    if (m) {
      var h = {};
      h[m[1]] = m[2];
      source.putLoginHeader(JSON.stringify(h));
      Log.debug(`登录头已注入：${m[1]}`);
    }
  } catch (e) { Log.warn(`读取登录 Cookie 失败：${e}`); }
}

/* ===== 工具 ===== */
function escapeHtml(s) {
  if (!s) return '';
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function getZSFontCss(fontId, weight) {
 var uri = "https://fontsapi.zeoseven.com/" + fontId + "/" + weight + "/"; 
 var url = uri + "result.css"; 
 var cacheKey = java.md5Encode16(url);
 var cached = cache.getFile(cacheKey);
 if (cached && cached!='') { return cached; } 
 else { var css = String(java.cacheFile(url))
   .replace(/url\("\.\//g, 'url("' + uri)
   .replace(/ur\('\.\//g, "url('" + uri);
   cache.putFile(cacheKey, css, 0);
   return css; }
}
function getHlsJs() {
 var url = "https://cdn.jsdelivr.net/npm/hls.js@1/dist/hls.min.js";
 var cacheKey = java.md5Encode16(url);
 var cached = cache.getFile(cacheKey);
 if (cached && cached!='') { return cached; } 
 else {var js = String(java.cacheFile(url));
   cache.putFile(cacheKey, js, 0);
  return js; }
}

/* ===== 提取数据 ===== */
function getPostData() {
  const g = (rule) => java.getString(rule) || '';
  const n = (rule) => Number(java.getString(rule)) || 0;
  const z = (rule) => g(rule) || '0';
  var postId = '', blogId = '';
  try { postId = g('$..post.id'); blogId = g('$..post.blogId'); }
  catch (e) { Log.warn(`postId / blogId 提取失败：${e}`); }

  /* 字段提取 */
  const errMsg = g('$..msg');
  const titleRaw = g('$..post.title||$..post.longInfo.title');
  const content = g('$..post.content||$..post.longInfo.content');
  const coName = g('$..postCollection.name');
  const coId = g('$..postCollection.id');
  const coDesc = g('$..postCollection.description');
  const coBlogId = g('$..postCollection.blogId') || blogId;
  const blogUrl = g('$..blogPageUrl');
  const blogName = g('$..blogInfo.blogName');
  const authorName = g('$..blogInfo.blogNickName');
  const authorImg = g('$..blogInfo.bigAvaImg');
  const tagsRaw = g('$..tag');
  const photoLinks = g('$..photoLinks');
  const embedData = g('$..embed');
  const imagesUrl = g('$..post.firstImageUrl');
  const publishTime = n('$..post.publishTime');
  const modifyTime = n('$..post.modifyTime');
  const showGift = n('$..showGift');
  const showAudio = n('$..showAudio');
  const audioListen = n('$..audioPostVO.listenCount');
  const favorite = z('$..postCount.favoriteCount');
  const response = z('$..postCount.responseCount');
  const subscribe = z('$..postCount.subscribeCount'); 
  const share = z('$..postCount.shareCount');
  const showVote = /^(true|1)$/i.test(String(g('$..showVote')));  
  /* 回礼解析 */
  var returnContent = [];
  try { var posts = (JSON.parse(src).response || {}).posts || []; 
    posts.forEach(p => {
      var list = (p && p.post && p.post.returnContent) || [];
      list.forEach(rc => {
        if (rc && rc.content) returnContent.push({
          title: rc.planTypeName ? `🎈 ${rc.planTypeName}` : '',
          content: rc.content || '',
          images: rc.images || []
    });});});
  } catch (e) { Log.warn(`回礼解析失败：${e}`); }
  /* 回礼未解锁 → 拉卡片 */
  if (showGift > 0 && !returnContent.length && postId && blogId) { 
    var si = fetchSupportInfo(postId, blogId, coId); 
    var rg = si && si.returnGifts && si.returnGifts[0]; 
    if (rg) returnContent.push({ title: '', content: buildSupportCard(rg, blogUrl), images: [] }); 
  }
  /* 投票处理 */
  if (showVote && postId && blogId) {
    var vh = buildVoteCard(postId, blogId, blogUrl);
    if (vh) returnContent.push({ title: '', content: vh, images: [] });
  }
  /* 数据删缺 */
  var deleted = /删除|不存在|下架|失效|不可见/i.test(errMsg)
    || (!postId && !blogId && !titleRaw && !content && !authorName);

  return {
    postId, blogId, blogUrl, blogName,
    coId, coBlogId, coName, coDesc,
    titleRaw, tagsRaw,
    authorImg, authorName,
    publishTime, modifyTime,
    photoLinks, imagesUrl, embedData,
    favorite, response,subscribe, share,
    showGift, showAudio, audioListen,
    content, returnContent,
    errMsg, deleted
  };
}

/* ===== 页面 ===== */
/* 首图组（无正文图时兜底） */
function buildFirstImageHtml(json) {
  if (!json) return '';
  try {
    var urls = JSON.parse(json);
    if (!urls.length) return '';
    var html = '<div class="iv iv--first"><div class="iv-stage">';
    for (var i = 0; i < urls.length; i++) {
      if (!urls[i]) continue;
      html += `
<div class="iv-slide ${i===0?'active':''}" data-index="${i}"><img src="${escapeHtml(urls[i])}" alt="图片" ${i>0?'loading="lazy"':''}><span class="iv-bar"><button class="iv-btn iv-zoom" type="button" tite="放大"><i class="fa fa-search-plus" aria-hidden="true"></i></button><button class="iv-btn iv-open" type="button" title="查看"><i class="fa fa-location-arrow" aria-hidden="true"></i></button><span class="iv-page">${i+1}/${urls.length}</span></span></div>`;
    }
    return html + '</div></div>';
  } catch (e) { Log.warn(`firstImageUrl 解析失败：${e}`); return ''; }
}

/* 图组 */
function buildImageHtml(json) {
  if (!json) return '';
  try {
    var ps = JSON.parse(json);
    var html = '<div class="iv"><div class="iv-stage">';
    for (var i = 0; i < ps.length; i++) {
      var u = ps[i].orign || ps[i].small || ps[i].url || '';
      if (!u) continue;
      html += `
<div class="iv-slide ${i===0?'active':''}" data-index="${i}"><img src="${escapeHtml(u)}" alt="图片" ${i>2?'loading="lazy"':''}><span class="iv-bar"><button class="iv-btn iv-zoom" type="button"title="放大"><i class="fa fa-search-plus" aria-hidden="true"></i></button><button class="iv-btn iv-open" type="button" title="查看"><i class="fa fa-location-arrow" aria-hidden="true"></i></button><span class="iv-page">${i+1}/${ps.length}</span></span></div>`;  
    }
    return html + '</div></div>';
  } catch (e) { Log.warn(`photoLinks 解析失败：${e}`); return ''; }
}

/* 视频 */
function buildVideoHtml(json) {
  if (!json || json.indexOf("originUrl") === -1) return '';
  try {
    var u = JSON.parse(json).originUrl;
    return u ? `<div class="video"><iframe src="${escapeHtml(u)}" sandbox="allow-scripts allow-same-origin" allow="accelerometer; gyroscope; magnetometer" allowfullscreen></iframe></div>` : '';
  } catch (e) { Log.warn(`embed 解析失败：${e}`); return ''; }
}

/* 作者栏 */
function buildAuthorHtml(img, name) {
  var authorAvatar = `<img src="${escapeHtml(img).replace(/\?.+$/,'')}?imageView&thumbnail=84x84&stripmeta=0&quality=90&type=webp&typefallback=jpg" class="post-author__avatar" onerror="this.style.display='none'">`; 
  return '<div class="post-author">' + authorAvatar + 
  '<span class="post-author__name">' + escapeHtml(name) + '</span>' + 
  '<span class="btn btn--follow" data-action="follow" title="关注作者"><i class="fa fa-user"></i></span>' + 
  '<span class="btn btn--article-add" data-action="article-add" title="收藏文章"><i class="fa fa-asterisk"></i></span>' + 
  '<span class="btn btn--collection-trigger" data-action="collection-trigger" title="合集列表"><i class="fa fa-slack"></i></span>' + 
  '</div>';
}

/* 段落处理 */
function processParagraphs(html) {
  if (!html) return html;
  var idx = 0;

  return String(html).replace(/<p\b([^>]*)>([\s\S]*?)<\/p>/gi, (m, attrs, content) => {
    var fallbackPid = 'p_i' + idx;
    var idm = attrs.match(/\bid="([^"]*)"/i);
    var actualPid = idm ? idm[1] : fallbackPid;
    if (!idm) attrs += ` id="${fallbackPid}"`;
    idx++;

    var c = content
      .replace('&type=jpg', '')
      .replace(/(\s*<br\s*\/?>\s*)+/gi, '<br>')
      .replace(/<[a-z]{1,10}>\s*<\/[a-z]{1,10}>\s*/gi, '')
      .replace(/\[\s+/g, '[').replace(/\s+\]/g, ']')
      .replace(/【\s+/g, '【').replace(/\s+】/g, '】')
      .replace(/〖\s+/g, '〖').replace(/\s+〗/g, '〗')
      .replace(/^[　\s]+$/g, '').trim()
      .split(/(<[^>]+>)/).map(p => p[0] === '<' ? p : p.trim()).join('');

    if (/^(?:\s|　|<br>|&nbsp;|&#160;|&#xa0;)*$/i.test(c)) {
      attrs = /\bstyle\s*=/i.test(attrs) ?
        attrs.replace(/\bstyle\s*=\s*(['"])([\s\S]*?)\1/i,
          (_, q, s) => ` style=${q}${s.replace(/;\s*$/,'')};display:none;${q}`) :
        attrs.trim() + ' style="display:none"';
      return `<p ${attrs}></p>`;
    }
    if (!/^\u3000/.test(c)) c = '\u3000' + c;

    return `<p ${attrs.trim()}>${c}</p>`;
  });
}

/* 付费内容（已解锁） */
function buildUnlockHtml(list) {
  if (!list || !list.length) return '';
  return list.map(item => {
    var imgs = '';
    if (item.images && item.images.length) {
      imgs = '<div class="unlock-item__images">';
      item.images.forEach(img => {
        var u = img.orign || img.raw || img.url || '';
        if (u) imgs += `<img src="${escapeHtml(u)}" alt="回礼图片">`;
      });
      imgs += '</div>';
    }
    var title = item.title ? `<div class="unlock-item__title">${escapeHtml(item.title)}</div>` : '';
    return `<div class="unlock-item">${title}<div class="unlock-item__content">${item.content}</div>${imgs}</div>`;
  }).join('');
}

/* 付费内容（未解锁） */
function fetchSupportInfo(pid, bid, cid) {
  if (!pid || !bid) return null;
  /* 移去下述内置函数 encodeURIComponent() */
  var q = `postId=${pid}&blogId=${bid}&openFansVipPlan=0&vipFans=0${cid?`&collectionId=${cid}`:''}&scene=note&postType=1`;
  try {
    var d = JSON.parse(java.ajax(`https://api.lofter.com/v1.1/trade/gift/post/newSupportInfo?${q}`));
    if (d && d.code === 200) return d.data;
  } catch (e) { Log.warn(`newSupportInfo 拉取失败：${e}`); }
  return null;
}
function buildSupportCard(rg, url) {
  var tags = [];
  var appUrl = /^https:/.test(url) ? url.replace('https:', 'lofter:') : '';
  (rg.labels || []).forEach(l => tags.push(`<span class="support-tag">${escapeHtml(l.label)}</span>`));
  (rg.feedbacks || []).forEach(f => tags.push(`<span class="support-tag support-tag--comment">${escapeHtml(f)} <i class="fa fa-angle-right"></i></span>`));

  var plan = (rg.planType && rg.planType.name) || '';
  var badge = plan ? `<span class="support-badge">${escapeHtml(plan)}</span>` : '';
  var title = rg.title ? `<span class="support-title">${escapeHtml(rg.title)}</span>` : '<span class="support-title">惊喜衍生剧场</span>';
  var appBtn = appUrl ? `<button class="support-app-btn" type="button" onclick="java.openUrl('${escapeHtml(appUrl)}')" title="在 App 中打开">${logoData()}</button>` : '';
  var header = (badge || title) ? `<div class="support-header">${badge}${title}${appBtn}</div>` : '';
  const lockCount = [
    rg.wordCount > 0 && `${rg.wordCount} 字`,
    rg.imgCount > 0 && `${rg.imgCount} 图`
  ].filter(Boolean).join(' + ');

  return `<div class="support-card">${header}` +
    (tags.length ? `<div class="support-tags">${tags.join('')}</div>` : '') +
    (rg.promotion ? `<div class="support-promotion">${escapeHtml(rg.promotion)}</div>` : '') +
    (rg.digest ? `<div class="support-digest">${escapeHtml(rg.digest).trim().replace(/\s+/g,'<br>')}...</div>` : '') +
    (lockCount ? `<div class="support-lock"><i class="fa fa-lock"></i><span>解锁余 ${lockCount}</span></div>` : '') +
    '</div>';
}

/* 投票详情 */
function buildVoteCard(pid, bid, url) {
  try {
    var d = JSON.parse(java.ajax(`https://api.lofter.com/newapi/vote/detail.json?postId=${pid}&blogId=${bid}`)); 
    var vo = d && d.data && d.data.voteInfoVO;
    if (!vo || !Array.isArray(vo.voteOptionList) || !vo.voteOptionList.length) return '';
    var total = 0;
    vo.voteOptionList.forEach(function(o){ total += Number(o.count) || 0; });
    var votedId = Number(vo.votedOptionId) || 0;
    var appUrl = /^https:/.test(url) ? url.replace('https:', 'lofter:') : '';
    var appBtn = appUrl ? `<button class="support-app-btn" type="button" onclick="java.openUrl('${escapeHtml(appUrl)}')" title="在 App 中打开">${logoData()}</button>` : '';
    var rows = vo.voteOptionList.map(function(o){
      var c = Number(o.count) || 0;
      var pct = total > 0 ? Math.round(c * 100 / total) : 0;
      var cls = (votedId && Number(o.id) === votedId) ? 'vote-row voted' : 'vote-row';
      return `<div class="${cls}"><span class="vote-bar" style="width:${pct}%"></span><span class="vote-name">${escapeHtml(o.optionContent || '')}</span><span class="vote-num">${c} · ${pct}%</span></div>`;
    }).join('');
    var badge = Number(vo.status) === 1 ? '投票' : '投票已结束';
    return `<div class="vote-card"><div class="vote-title"><b>${badge}</b><span class="vote-title__text">${escapeHtml(vo.title || '')}</span>${appBtn}</div>${rows}<div class="vote-foot">共 ${(Number(vo.joinCount) || total)} 人参与</div></div>`; 
  } catch (e) { Log.warn('vote 拉取失败：' + e); return ''; }
}

/* 合集 */
function buildCollectionHtml(name, desc, listen) {
  if (name) name = String(name).trim();
  if (!name) return '';
  var tts = listen? '<span class="btn btn--tts" data-action="tts" title="听书"><i class="fa fa-listen" aria-hidden="true"></i></span>' : '';
  var html = `<div class="post-col"><span class="post-col__label">合集: </span><span class="post-col__info" data-action="collection-info" title="查看合集">${escapeHtml(name)}</span><span class="btn btn--import" data-action="collection-import" title="收藏合集"><i class="fa fa-bookmark" aria-hidden="true"></i></span><span class="btn btn--open" data-action="collection-open" title="打开合集"><i class="fa fa-folder" aria-hidden="true"></i></span>${tts}</div>`;
  if (desc && String(desc).trim()) html += `<div><details class="post-col__details"><summary></summary><div class="post-col__desc">${escapeHtml(desc)}</div></details></div>`;
  return html;
}

/* 标签 */
function buildTagsHtml(raw) {
  if (!raw) return '';
  var parts = ['<div class="post-tags"><span class="post-tags__label">标签: </span>'];
  raw.split(',').forEach(t => { t = t.trim(); if (t) parts.push(`<span class="post-tags__item">${escapeHtml(t)}</span>`); });
  return parts.join('') + '</div>';
}

/* 计数 */
function buildCountsHtml(fav, resp, sub, share, gift, audio, listen) {
  const itemGift = gift!=0?`<span class="post-counts__item p-count-showgift">${gift}</span>`:'';
  const itemAudio = audio!=0?`<span class="post-counts__item p-count-showaudio">${listen}</span>`:''; 
  return '<div class="post-counts">' +
 `<span class="post-counts__item p-count-favorite">${fav}</span>` + 
 `<span class="post-counts__item p-count-subscribe">${sub}</span>` + 
 `<span class="post-counts__item p-count-response">${resp}</span>` + 
 `<span class="post-counts__item p-count-share">${share}</span>` + 
  itemGift + itemAudio + 
  '</div>'; 
}

/* 底链  */
function buildLinksHtml(pid, bid, url) {
  return '<div class="post-links"><span>点击跳转: </span>' + 
  `<a href="https://www.lofter.com/comment.do?pid=${pid}&bid=${bid}&listlinkcolor=828d95&listcontentcolor=737373&listbordercolor=ddd&inputbordercolor=ddd">评论链接</a> ` + 
  `<a href="javascript:void(0)" onclick="java.openUrl('${escapeHtml(url)}')">查看原网页</a> ` + 
  '<a href="javascript:void(0)" data-action="export-ext">缓存文章</a>' + 
  '</div>';
}

/* ===== 组装 HTML ===== */
function assembleHtml(pd, cm) {
  if (pd.deleted) { return `<!DOCTYPE html><html lang="zh-CN"><head><meta charset="UTF-8"><title>作品已删除</title></head><body><div class="post-deleted"><div class="post-deleted__icon">🚫</div><div class="post-deleted__title">作品已删除或不可见</div><div class="post-deleted__desc">${escapeHtml(pd.errMsg||'')}</div></div></body></html>`; } 
  var cardHtml = ''; 
