(function() {
'use strict';

// if(window.__startInject) return;
// window.__startInject = true;
const HISTORY_KEY = 'lofHistory';
const VERSION_KEY = 'lofVersion';

// 宿主桥接
const Host = {
 ajax(u) { try { return java.ajax(String(u)); } catch (e) { return null; } },
 toast(m) { try { java.toast(String(m)); } catch (e) {} },
 open(k, u, t) { try { if(t) java.open(String(k), String(u), String(t)); else java.open(String(k), String(u)); } catch (e) {} },
 openUrl(u) { try { java.openUrl(String(u)); } catch (e) {} },
 connect(u) { try { java.connect(String(u)); } catch (e) {} },
 getVariable() { try { return source.getVariable() || ''; } catch (e) { return ''; } },
 putVariable(v) { try { source.putVariable(String(v)); return true; } catch (e) { return false; } },
 // getVersion(){ try{ const v = source.get(VERSION_KEY); return v == null ? 0 : (Number(v) || 0); }catch(e){ return 0; } },
 putVersion(n) { try { source.put(VERSION_KEY, String(n)); return true; } catch (e) { return false; } },
 androidId() { try { return java.androidId() || ''; } catch (e) { return ''; } },
 base64Encode(s) { try { return java.base64Encode(String(s)); } catch (e) { return ''; } },
 timeFormatUTC(n, f, t) { try { return java.timeFormatUTC(n, f, t); } catch (e) { return ''; } },
 vibrate(ms) { try { if(navigator.vibrate) navigator.vibrate(ms); } catch (e) {} }
};

/* =====  常量 ===== */
const API_BASE = 'https://api.lofter.com';
const VER = { R1: '8.3.20', R2: '8.0.2', R3: '7.4.4', R4: '8.3.64' };
const DRAG_HOLD_MS = 350, DRAG_SLOP = 10;
const SCHEMA_VERSION = 1;

/* 类型 → Store 字段名，拖拽 / 排序共用同一张表 */
const TYPE_TO_FIELD = {
 tag:'tags', cleandTag:'cleandTags',
 col:'collections', author:'authors',
 article:'articles', history:'history'
};
/* 值本身就是字符串的类型 */
const STRING_TYPES = { tag: 1, cleandTag: 1 };

const PERSIST_FIELDS = [
 'tags','hiddenTags',
 'cleandTags','disCleandTags',
 'collections','authors','articles',
 'find','type','allType'
];
const PERSIST_SET = new Set(PERSIST_FIELDS);

const RANKS = [
 { sortNo: 1, type: 'hotword', label: '热词' },
 { sortNo: 3, type: 'hotarticle', label: '热文' },
 { sortNo: 5, type: 'hotuser', label: '太太' },
 { sortNo: 6, type: 'hottag', label: '游戏' },
 { sortNo: 7, type: 'hottag', label: '影视' },
 { sortNo: 8, type: 'hottag', label: '二次元' }
];

const ALL_TYPES = [
 { key: 'tag', label: '标签' },
 { key: 'col', label: '合集' },
 { key: 'author', label: '作者' },
 { key: 'article', label: '文章' }
];

const HDR_TAG_POST = JSON.stringify({
'accept-encoding':'gzip, deflate',
method:'POST',
body:'null'
});

const Hidden = { SHOW: '0', HIDE: '1', CLEAN: '2' };

/* =====  纯函数工具 ===== */
function trimStr(s) { return String(s == null ? '' : s).trim(); }

function findItem(arr, predicate) { return arr.find(predicate) || null; }

function escapeHtml(s) {
 return String(s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
}

function escapeAttr(o) { return escapeHtml(JSON.stringify(o)); }

function extractDigits(s) { const m = trimStr(s).match(/\d+/); return m ? m[0] : ''; }

function extractColId(s) {
 const t = trimStr(s);
 if(/^\d+$/.test(t)) return t;
 const m = t.match(/collection[Ii]d=(\d+)/i);
 return m ? m[1] : extractDigits(t);
}

function extractBlogId(s) {
 const t = trimStr(s);
 if(/^\d+$/.test(t)) return t;
 const m = t.match(/blog[Ii]d=(\d+)/i);
 if(m) return m[1];
 const h = t.match(/home-page\/([^\/?#]+)/);
 return h ? h[1].replace(/\.lofter\.com$/i, '') : extractDigits(t);
}

function parseColCount(s) {
 if(!s || typeof s !== 'string') return null;
 const p = s.split('/');
 if(p.length !== 3) return null;
 const o = parseInt(p[1], 10), n = parseInt(p[2], 10);
 if(isNaN(o) || isNaN(n)) return null;
 return { lastDate: p[0], oldCount: o, newCount: n };
}

function normalizeAllType(v) {
 const d = {};
 for (let i = 0; i < ALL_TYPES.length; i++) d[ALL_TYPES[i].key] = 1;
 if(!v || typeof v !== 'object') return d;
 for (let i = 0; i < ALL_TYPES.length; i++) {
  const k = ALL_TYPES[i].key;
  if(k in v) {
   const x = v[k];
   d[k] = (x === 0 || x === '0' || x === false || x === 'false') ? 0 : 1;
  }
 }
 return d;
}

function safeUrl(u) {
 if(!u) return '';
 u = String(u);
 if(/^https?:\/\//i.test(u)) return u;
 if(/^\/\//.test(u)) return 'https:' + u;
 if(/^data:image\//i.test(u)) return u;
 return '';
}

function stripHtml(s) {
 if(!s) return '';
 try {
  const doc = new DOMParser().parseFromString('<div>' + String(s) + '</div>', 'text/html');
  const el = doc.body.firstChild;
  return ((el && (el.textContent || '')) || '').replace(/\s+/g, ' ').trim();
 } catch (e) {
  return String(s).replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
 }
}

function getToday() {
 const d = new Date();
 return d.getFullYear() + ('0' + (d.getMonth() + 1)).slice(-2) + ('0' + d.getDate()).slice(-2);
}

function fmtUpdate(ts) {
  let n = +ts; if (!n) return '';
  if (n < 1e12) n *= 1000;
  // return Host.timeFormatUTC(n, 'YYYY/MM/dd HH:mm', 8);
  const h = (Date.now() - n) / 36e5;
  if (h < 1) return '刚刚';
  if (h < 24) return Math.floor(h) + '小时前';
  if (h < 48) return '昨天';
  if (h < 24 * 30) return Math.floor(h / 24) + '天前';
  if (h < 24 * 365) return Math.floor(h / 24 / 30) + '个月前';
  return Math.floor(h / 24 / 365) + '年前';
}


/* 显示键（visibleKeys）在全部（arr）中的数据重排 */
function reorderByKey(arr, visibleKeys, keyOf) {
 if(!Array.isArray(arr) || !Array.isArray(visibleKeys)) return arr;
 if(!visibleKeys.length) return arr;
 const keySet = new Set(visibleKeys);
 const bucket = new Map();
 for (let i = 0; i < arr.length; i++) {
  const k = keyOf(arr[i]);
  if(!keySet.has(k)) continue;
  if(!bucket.has(k)) bucket.set(k, []);
  bucket.get(k).push(arr[i]);
 }
 const ordered = [];
 for (let i = 0; i < visibleKeys.length; i++) {
  const q = bucket.get(visibleKeys[i]);
  if(q && q.length) ordered.push(q.shift());
 }
 let oi = 0;
 for (let i = 0; i < arr.length && oi < ordered.length; i++) {
  if(keySet.has(keyOf(arr[i]))) {
   arr[i] = ordered[oi++];
  }
 }
 return arr;
}

/* =====  配置规范化 ===== */
function normalizeCfg(cfg) {
 cfg = cfg || {};
 const arr = v => Array.isArray(v) ? v : [];
 return {
  cleandTags: arr(cfg.cleandTags).map(trimStr).filter(Boolean),
  disCleandTags: arr(cfg.disCleandTags).map(trimStr).filter(Boolean),
  tags: arr(cfg.tags).map(trimStr).filter(Boolean),
  collections: arr(cfg.collections).filter(c => c && typeof c === 'object').map(c => {
   const o = { name: trimStr(c.name), id: trimStr(c.id) };
   if(c.hidden != null) o.hidden = c.hidden;
   if(c.count != null) o.count = c.count;
   if(c.update && +c.update > 0) o.update = String(c.update);
   return o;
  }).filter(c => c.name && c.id),
  authors: arr(cfg.authors).filter(a => a && typeof a === 'object').map(a => {
   const o = { name: trimStr(a.name), blogId: trimStr(a.blogId) };
   if(a.hidden != null) o.hidden = a.hidden;
   if(a.avatar && trimStr(a.avatar) !== '') o.avatar = a.avatar;
   if(a.update && +a.update > 0) o.update = String(a.update);
   return o;
  }).filter(a => a.name && a.blogId),
  articles: arr(cfg.articles).filter(a => a && typeof a === 'object').map(a => ({
   title: trimStr(a.title),
   url: trimStr(a.url),
   hidden: String(a.hidden || Hidden.SHOW) === Hidden.HIDE ? Hidden.HIDE : Hidden.SHOW
  })).filter(a => a.title && a.url),
  hiddenTags: arr(cfg.hiddenTags).map(trimStr).filter(Boolean)
 };
}

/* =====  Store ===== */
const Store = (function() {
 const state = {
  tags: [], hiddenTags: [], cleandTags: [], disCleandTags: [],
  collections: [], authors: [], articles: [], history: [],
  find: '', type: '', allType: null,
  ui: {
   currentFilter: 'all',
   manageMode: false,
   showHidden: false,
   showCleandTags: false,
   subscrCollections: null,
   currentRank: null,
  }
 };
 const listeners = new Map();
 const dirtyFields = new Set();
 let flushTimer = null;
 let lastRaw = '';

 function on(ev, fn) {
  if(typeof fn !== 'function') return () => {};
  if(!listeners.has(ev)) listeners.set(ev, new Set());
  listeners.get(ev).add(fn);
  return () => { const s = listeners.get(ev); if(s) s.delete(fn); };
 }

 function emit(ev, payload) {
  const set = listeners.get(ev);
  if(!set) return;
  set.forEach(fn=>{
   try{ fn(payload); }catch(e){}
  });
 }

 function markDirty(fields){
  if(Array.isArray(fields)){
   for(let i=0;i<fields.length;i++) dirtyFields.add(fields[i]);
  }else if(fields) dirtyFields.add(fields);
 }

 function scheduleFlush() {
  if (flushTimer) return; flushTimer = true;
  queueMicrotask(() => { flushTimer = null; flush(); });
 }

 function flush() {
  flushTimer = null; if (!dirtyFields.size) return;
  const raw = Host.getVariable();
  let latest;
  if(raw && raw.trim()) {
   try { latest = JSON.parse(raw);
    if(!latest || typeof latest !== 'object' || Array.isArray(latest)) latest = null;
   } catch (e) { latest = null; }
   if(latest === null) return;
  } else {
   latest = {};
  }

  const flushedFields = [];
  dirtyFields.forEach(f => {
   if(!PERSIST_SET.has(f)) return;
   latest[f] = state[f];
   flushedFields.push(f);
  });

  const payload = JSON.stringify(latest);
  try {
   const roundTrip = JSON.parse(payload);
   if(!roundTrip || typeof roundTrip !== 'object' || Array.isArray(roundTrip)) throw new Error('round-trip');
  } catch (e) { return; }

  if(Host.putVariable(payload)) {
   Host.putVersion(SCHEMA_VERSION);
   dirtyFields.clear();
   lastRaw = Host.getVariable();
   emit('flush', { fields: flushedFields });
  }
 }

 /* ===== 历史记录（缓存版） ===== */
 function readHistory() {
  try {
   const raw = source.get(HISTORY_KEY);
   if(!raw || !raw.trim()) return [];
   const parsed = JSON.parse(raw);
   if(!Array.isArray(parsed)) return [];
   return parsed.filter(h => h && typeof h === 'object' && h.url).map(h => {
    const o = { title: trimStr(h.title), url: trimStr(h.url), time: Number(h.time) || 0 };
    if(h.collectionId) o.collectionId = trimStr(h.collectionId);
    if(h.collectionName) o.collectionName = trimStr(h.collectionName);
    return o;
   });
  } catch (e) { return []; }
 }

 function writeHistory() {
  try {
   const payload = JSON.stringify(state.history || []);
   if(!Array.isArray(JSON.parse(payload))) return false;
   source.put(HISTORY_KEY, payload);
   return true;
  } catch (e) { return false; }
 }

 // 载入变量
 function load() {
  const raw = Host.getVariable();
  lastRaw = raw;

  let parsed = null;
  if(raw && raw.trim()) { try { parsed = JSON.parse(raw); } catch (e) { parsed = null; } }
  if(!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) parsed = {};

  const normalized = normalizeCfg(parsed);
  state.tags = normalized.tags;
  state.hiddenTags = normalized.hiddenTags;
  state.cleandTags = normalized.cleandTags;
  state.disCleandTags = normalized.disCleandTags;
  state.collections = normalized.collections;
  state.authors = normalized.authors;
  state.articles = normalized.articles;
  state.history = readHistory();
  state.find = parsed.find || '';
  state.type = parsed.type || '';
  state.allType = normalizeAllType(parsed.allType);
  emit('load', state);
 }
 // 重载变量
 function reload() {
  const raw = Host.getVariable();
  if(raw === lastRaw) return false;
  load();
  return true;
 }

 function set(field, value, opts) {
  opts = opts || {};
  if(field === 'ui' || !(field in state)) return;
  if(state[field] === value) return;
  state[field] = value;
  if(PERSIST_SET.has(field)) {
   markDirty(field);
   if(opts.now) flush();
   else scheduleFlush();
  }
  emit('change:' + field, value);
  emit('change', { field, value });
  if(opts.render !== false) emit('render', { field });
 }

 function mutate(field, fn, opts) {
  opts = opts || {};
  if(field === 'ui' || !(field in state)) return;
  const next = fn(state[field]);
  if(next === undefined) return;
  state[field] = next;
  if(PERSIST_SET.has(field)) {
   markDirty(field);
   if(opts.now) flush();
   else scheduleFlush();
  }
  emit('change:' + field, next);
  emit('change', { field, value: next });
  if(opts.render !== false) emit('render', { field });
 }

 function getUI(key) { return state.ui[key]; }

 function setUI(key, value, opts) {
  opts = opts || {};
  if(!(key in state.ui) || state.ui[key] === value) return;
  state.ui[key] = value;
  emit('ui:' + key, value);
  if(opts.render !== false) emit('render', { ui: key });
 }

 /* 原子追加 */
 function appendField(field, item, dupFn, opts) {
  if(!PERSIST_SET.has(field)) return 'fail';

  const raw = Host.getVariable();
  let latest;
  if(raw && raw.trim()) {
   try {
    latest = JSON.parse(raw);
    if(!latest || typeof latest !== 'object' || Array.isArray(latest)) return 'fail';
   } catch (e) { return 'fail'; }
  } else {
   latest = {};
  }

  if(!Array.isArray(latest[field])) latest[field] = [];

  if(dupFn && latest[field].some(dupFn)) {
   state[field] = latest[field];
   lastRaw = raw;
   emit('change:' + field, state[field]);
   emit('render', { field });
   return 'dup';
  }

  if(opts && opts.prepend) latest[field].unshift(item);
  else latest[field].push(item);

  const payload = JSON.stringify(latest);
  try {
   const r = JSON.parse(payload);
   if(!r || typeof r !== 'object' || Array.isArray(r)) return 'fail';
  } catch (e) { return 'fail'; }

  if(!Host.putVariable(payload)) return 'fail';
  state[field] = latest[field];
  lastRaw = Host.getVariable();
  Host.putVersion(SCHEMA_VERSION);
  emit('change:' + field, state[field]);
  emit('change', { field, value: state[field] });
  emit('render', { field });
  return 'ok';
 }

 return {
  state, PERSIST_FIELDS,
  // get(f){ return state[f]; },
  set, mutate,
  getUI, setUI,
  appendField,
  on, emit,
  load, reload, flush, markDirty, scheduleFlush,
  reloadHistory() { state.history = readHistory(); },
  saveHistory() { return writeHistory(); }
 };
})();

