/* =====  请求层 ===== */
const REQ_RETRY = 1;
const REQ_RETRY_DELAY = 250;

function requestRaw(url, opts) {
 opts = opts || {};
 const retries = opts.retries == null ? REQ_RETRY : opts.retries;
 return new Promise((resolve) => {
  let attempt = 0;

  function run() {
   const raw = Host.ajax(url);
   if(raw) { resolve(raw); return; }
   if(attempt++ < retries) setTimeout(run, REQ_RETRY_DELAY * attempt);
   else resolve(null);
  }
  run();
 });
}

async function ajaxJson(url, opts) {
 const raw = await requestRaw(url, opts);
 if(!raw) return null;
 try { return JSON.parse(raw); } catch (e) { return null; }
}

function runAsync(promise, opts) {
 opts = opts || {};
 return Promise.resolve(promise).catch(() => {
  if(opts.silent !== true) Host.toast('操作失败，请重试');
 });
}

