/* =====  主渲染 ===== */
// 分片渲染
var CHUNK_SIZE = 40;
var _chunkToken = 0;
function insertHtmlChunked(wrap, html, chunkSize) {
 const size = chunkSize || CHUNK_SIZE;
 const tmp = document.createElement('div');
 tmp.innerHTML = html;
 const children = Array.from(tmp.childNodes);
 if(children.length <= size) {
  wrap.innerHTML = html;
  return;
 }
 const token = ++_chunkToken;
 wrap.innerHTML = '';
 let i = 0;
 (function pump() {
  if(token !== _chunkToken) return;
  const frag = document.createDocumentFragment();
  const end = Math.min(i + size, children.length);
  for(; i < end; i++) frag.appendChild(children[i]);
  wrap.appendChild(frag);
  if(i < children.length) requestAnimationFrame(pump);
 })();
}
// 渲染进程
function render() {
 const windowY = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
 const containerY = container.scrollTop;
 const nodes = ensureSections();
 let anyVisible = false;

 for (let i = 0; i < SECTION_DEFS.length; i++) {
  const key = SECTION_DEFS[i][0];
  const renderFn = SECTION_DEFS[i][1];
  const html = renderFn();
  if(html === sectionHtmlCache[key]) {
   if(html) anyVisible = true;
   continue;
  }
  sectionHtmlCache[key] = html;
  const wrap = nodes[key];
  if(wrap.innerHTML !== html) insertHtmlChunked(wrap, html);
  if(html) anyVisible = true;
 }

 let emptyEl = container.querySelector('.empty');
 if(!anyVisible) {
  if(!emptyEl) {
   emptyEl = document.createElement('div');
   emptyEl.className = 'empty';
   emptyEl.textContent = '暂无内容';
   container.appendChild(emptyEl);
  }
 } else if(emptyEl && emptyEl.parentNode) {
  emptyEl.parentNode.removeChild(emptyEl);
 }

 /* 同步方案 */
 // if(container.scrollTop !== containerY) container.scrollTop = containerY;
 // if(window.pageYOffset !== windowY) window.scrollTo(0, windowY);
 /* 异步方案 */
 requestAnimationFrame(() => {
  if(container.scrollTop !== containerY) container.scrollTop = containerY;
  if(window.pageYOffset !== windowY) window.scrollTo(0, windowY);
 });
}

/* =====  隐藏与状态辅助 ===== */
function shouldShow(hiddenFlag) { return Store.getUI('showHidden') ? true : !hiddenFlag; }

function isHidden(item, type) {
 if(type === 'tag') return Store.state.hiddenTags.indexOf(item) !== -1;
 if(type === 'col') return String(item.hidden) === Hidden.HIDE || item.hidden === 1;
 if(type === 'author') {
  const stateStr = String(item.hidden == null ? Hidden.SHOW : item.hidden);
  return stateStr === Hidden.HIDE || stateStr === Hidden.CLEAN;
 }
 if(type === 'article') return String(item.hidden == null ? Hidden.SHOW : item.hidden) === Hidden.HIDE;
 return false;
}

function updateRow(rowEl, item, type) {
 if(!rowEl) return;
 let fresh = item;
 if(type === 'col') fresh = findItem(Store.state.collections, c => String(c.id) === String(item.id) && c.name === item.name) || item;
 else if(type === 'article') fresh = findItem(Store.state.articles, a => a.url === item.url && a.title === item.title) || item;
 else if(type === 'author') fresh = findItem(Store.state.authors, a => String(a.blogId) === String(item.blogId)) || item;

 let isItemHidden, eyeIcon;
 if(type === 'cleandTag') {
  const disabled = Store.state.disCleandTags.indexOf(item) !== -1;
  isItemHidden = disabled;
  eyeIcon = disabled ? svg.eyeClosed : svg.eyeCleand;
 } else if(type === 'author') {
  const hiddenState = String(fresh.hidden || Hidden.SHOW);
  isItemHidden = hiddenState === Hidden.HIDE || hiddenState === Hidden.CLEAN;
  eyeIcon = hiddenState === Hidden.HIDE ? svg.eyeClosed : hiddenState === Hidden.CLEAN ? svg.eyeCleand : svg.eyeOpen;
  rowEl.dataset.hidden = hiddenState;
  rowEl.classList.toggle('cleand-author-item', hiddenState === Hidden.CLEAN);
 } else {
  isItemHidden = isHidden(fresh, type);
  eyeIcon = isItemHidden ? svg.eyeClosed : svg.eyeOpen;
 }
 rowEl.classList.toggle('hidden-item', isItemHidden);
 const eyeBtn = rowEl.querySelector('.eye-btn');
 if(eyeBtn) eyeBtn.innerHTML = eyeIcon;
 invalidateSection(
  type === 'tag' || type === 'cleandTag' ? 'tags' :
  type === 'col' ? 'cols' :
  type === 'author' ? 'authors' :
  type === 'article' ? 'articles' : null
 );
}

/* =====  隐藏切换 ===== */
function toggleItem(item, type, rowEl) {
 const opts = { render: false };
 if(type === 'tag') {
  Store.mutate('hiddenTags', list => {
   const i = list.indexOf(item);
   i === -1 ? list.push(item) : list.splice(i, 1);
   return list;
  }, opts);
 } else if(type === 'col') {
  Store.mutate('collections', list => {
   const target = list.find(x => String(x.name) === item.name && String(x.id) === String(item.id));
   if(target) target.hidden = (String(target.hidden) === Hidden.HIDE || target.hidden === 1) ? Hidden.SHOW : Hidden.HIDE;
   return list;
  }, opts);
 } else if(type === 'author') {
  Store.mutate('authors', list => {
   const target = list.find(a => String(a.blogId) === String(item.blogId));
   if(!target) return list;
   const current = String(target.hidden || Hidden.SHOW);
   target.hidden = (Store.getUI('manageMode') && Store.getUI('showHidden')) ?
    (current === Hidden.SHOW ? Hidden.HIDE : current === Hidden.HIDE ? Hidden.CLEAN : Hidden.SHOW) :
    (current === Hidden.SHOW ? Hidden.HIDE : Hidden.SHOW);
   return list;
  }, opts);
 } else if(type === 'article') {
  Store.mutate('articles', list => {
   const target = list.find(a => a.title === item.title && a.url === item.url);
   if(target) target.hidden = String(target.hidden) === Hidden.HIDE ? Hidden.SHOW : Hidden.HIDE;
   return list;
  }, opts);
 }
 updateRow(rowEl, item, type);
}

function toggleCleand(tag, rowEl) {
 Store.mutate('disCleandTags', (list) => {
  const i = list.indexOf(tag);
  if(i === -1) list.push(tag); else list.splice(i, 1);
