/* =====  增删改 ===== */
function delItem(item, type) {
 Store.reload();
 const message = type === 'tag' ? `确定删除标签「${item}」？` :
  type === 'cleandTag' ? `确定删除屏蔽词「${item}」？` :
  type === 'col' ? `确定移除合集「${item.name}」？` :
  type === 'author' ? `确定移除作者「${item.name}」？` :
  type === 'article' ? `确定移除文章「${item.title}」？` :
  type === 'history' ? `确定移除历史「${item.title}」？` : '';
 if(!message || !confirm(message)) return;

 if(type === 'tag') {
  Store.mutate('tags', (l) => { const i = l.indexOf(item); if(i !== -1) l.splice(i, 1); return l; });
  Store.mutate('hiddenTags', (l) => l.filter(x => x !== item), { render: false });
  Host.toast('标签已删除');
 } else if(type === 'cleandTag') {
  Store.mutate('cleandTags', (l) => { const i = l.indexOf(item); if(i !== -1) l.splice(i, 1); return l; });
  Store.mutate('disCleandTags', (l) => { const j = l.indexOf(item); if(j !== -1) l.splice(j, 1); return l; }, { render: false });
  Host.toast('屏蔽词已删除');
 } else if(type === 'col') {
  Store.mutate('collections', (l) => l.filter(c => !(c.name === item.name && String(c.id) === String(item.id))));
  Host.toast('合集已移除');
 } else if(type === 'author') {
  Store.mutate('authors', (l) => l.filter(a => String(a.blogId) !== String(item.blogId)));
  Host.toast('作者已移除');
 } else if(type === 'article') {
  Store.mutate('articles', (l) => l.filter(a => !(a.title === item.title && a.url === item.url)));
  Host.toast('文章已移除');
 } else if(type === 'history') {
  Store.mutate('history', (l) => l.filter(a => a.url !== item.url), { render: false });
  Store.saveHistory(); Host.toast('历史已移除');
 }
 invalidateSection();
 render();
}

function editItem(item, type, button) {
 Store.reload();
 const rowEl = button.closest('.item');
 if(!rowEl) return;
 const nameSpan = rowEl.querySelector('.name-text');
 if(!nameSpan) return;
 rowEl.classList.add('editing');
 rowEl.style.width = rowEl.getBoundingClientRect().width + 'px';
 rowEl.style.flexShrink = '0';
 const currentName = type === 'tag' ? item : type === 'article' ? item.title : item.name;
 const input = document.createElement('input');
 input.type = 'text';
 input.value = currentName;
 input.className = 'edit-input';
 input.style.flex = '1 1 auto';
 input.style.minWidth = '0';
 const idSpan = rowEl.querySelector('.id-text');
 if(idSpan) idSpan.style.display = 'none';
 nameSpan.replaceWith(input);
 input.focus();
 input.addEventListener('click', e => e.stopPropagation());
 input.addEventListener('mousedown', e => e.stopPropagation());
 let finished = false;

 function finish(save) {
  if(finished) return;
  finished = true;
  rowEl.classList.remove('editing');
  const newName = input.value.trim();
  if(save && newName && newName !== currentName) {
   Store.reload();
   let ok = false;
   if(type === 'tag') {
    Store.mutate('tags', (l) => {
     let i = l.indexOf(item);
     if(i === -1) i = l.indexOf(newName);
     if(i !== -1) { l[i] = newName; ok = true; }
     return l;
    }, { render: false });
    Store.mutate('hiddenTags', (l) => l.map(x => x === item ? newName : x), { render: false });
   } else if(type === 'col') {
    Store.mutate('collections', (l) => {
     const target = l.find(x => x.name === item.name && String(x.id) === String(item.id));
     if(target) { target.name = newName; ok = true; }
     return l;
    }, { render: false });
   } else if(type === 'author') {
    Store.mutate('authors', (l) => {
     const target = l.find(x => String(x.blogId) === String(item.blogId));
     if(target) { target.name = newName; ok = true; }
     return l;
    }, { render: false });
   } else if(type === 'article') {
    Store.mutate('articles', (l) => {
     const target = l.find(x => x.title === item.title && x.url === item.url);
     if(target) { target.title = newName; ok = true; }
     return l;
    }, { render: false });
   }
   if(ok) {
    Store.flush();
    const label = { tag: '标签', col: '合集', author: '作者', article: '文章' } [type] || '项';
    Host.toast(`${label}名称已修改为「${newName}」`);
   } else {
    Host.toast('目标项已不存在，可能已被外部修改');
   }
   invalidateSection();
   render();
  } else {
   invalidateSection();
   render();
  }
 }
 input.addEventListener('keydown', e => {
  if(e.key === 'Enter') { e.preventDefault(); finish(true); }
  else if(e.key === 'Escape') { e.preventDefault(); finish(false); }
 });
 input.addEventListener('blur', () => setTimeout(() => finish(true), 0));
}

async function addItem(type) {
 Store.reload();
 try {
  if(type === 'tag') {
   const value = newTagInput.value.trim();
   if(!value) { Host.toast(Store.getUI('showCleandTags') ? '请输入屏蔽词' : '请输入标签名称'); return; }
   if(Store.getUI('showCleandTags')) {
    const r = Store.appendField('cleandTags', value, x => x === value);
    if(r === 'dup') { Host.toast('该屏蔽词已存在'); return; }
    if(r !== 'ok') { Host.toast('写入失败，请重试'); return; }
    /* 同名的 disCleandTags 项顺带清掉 */
    Store.mutate('disCleandTags', (l) => {
     const i = l.indexOf(value);
     if(i !== -1) l.splice(i, 1);
     return l;
    }, { render: false });
    Store.flush();
    Host.toast(`屏蔽词「${value}」已添加`);
   } else {
    const r = Store.appendField('tags', value, x => x === value);
    if(r === 'dup') { Host.toast('标签已存在'); return; }
    if(r !== 'ok') { Host.toast('写入失败，请重试'); return; }
    Host.toast(`标签「${value}」已添加`);
   }
   newTagInput.value = '';
   invalidateSection();
   render();
  } else if(type === 'col') {
   const nameInput = document.getElementById('newColNameInput');
   const idInput = document.getElementById('newColIdInput');
   let name = nameInput.value.trim();
   const id = extractColId(idInput.value);
   if(!id) { Host.toast('请输入合集ID或链接'); return; }
   if(!/^\d+$/.test(id)) { Host.toast('合集ID必须为数字'); return; }
   if(!name) {
    name = await fetchColName(id);
    if(!name) { Host.toast('无法自动获取合集名称，请手动填写'); return; }
    nameInput.value = name;
   }
   const r = Store.appendField('collections', { name, id }, x => x && String(x.id) === id);
   if(r === 'dup') { Host.toast('合集已存在'); return; }
   if(r !== 'ok') { Host.toast('写入失败，请重试'); return; }
   nameInput.value = ''; idInput.value = '';
   Host.toast(`合集「${name}」已添加`);
   invalidateSection();
   render();
  } else if(type === 'author') {
   const nameInput = document.getElementById('newAuthorNameInput');
   const idInput = document.getElementById('newAuthorIdInput');
   let name = nameInput.value.trim();
   const blogId = extractBlogId(idInput.value);
   if(!blogId) { Host.toast('请输入作者BID或链接'); return; }
   if(!/^\d+$/.test(blogId)) { Host.toast('作者BID必须为数字'); return; }
   if(!name) {
    name = await fetchAuthor(blogId);
    if(!name) { Host.toast('无法自动获取作者名称，请手动填写'); return; }
    nameInput.value = name;
   }
   const r = Store.appendField('authors', { name, blogId: blogId }, x => x && String(x.blogId) === blogId);
   if(r === 'dup') { Host.toast('作者已存在'); return; }
   if(r !== 'ok') { Host.toast('写入失败，请重试'); return; }
   nameInput.value = ''; idInput.value = '';
   Host.toast(`作者「${name}」已添加`);
   invalidateSection();
   render();
  } else if(type === 'article') {
   const titleInput = document.getElementById('newArticleTitleInput');
   const urlInput = document.getElementById('newArticleUrlInput');
   let title = titleInput.value.trim();
   const url = urlInput.value.trim();
   if(!url) { Host.toast('请输入文章链接'); return; }
   if(!/^https?:\/\//i.test(url)) { Host.toast('链接需以 http(s):// 开头'); return; }
   if(!title) {
    const fetched = await fetchArticleTitle(url);
    if(!fetched) { Host.toast('无法自动获取标题，请手动填写'); return; }
    title = fetched;
    titleInput.value = fetched;
   }
   const r = Store.appendField('articles', { title, url, hidden: Hidden.SHOW }, x => x && x.url === url, { prepend: true });
   if(r === 'dup') { Host.toast('文章链接已存在'); return; }
   if(r !== 'ok') { Host.toast('写入失败，请重试'); return; }
   titleInput.value = ''; urlInput.value = '';
   Host.toast(`文章「${title}」已添加`);
   invalidateSection();
   render();
  }
 } catch (e) {
  Host.toast('添加失败');
 }
}

