/* =====  拖拽排序 ===== */
let dragState = null, holdTimer = null, holdTarget = null;
let holdStartX = 0, holdStartY = 0, suppressClickUntil = 0;

function arrForType(type) { return TYPE_TO_FIELD[type] ? Store.state[TYPE_TO_FIELD[type]] : null; }

function fieldForType(type) { return TYPE_TO_FIELD[type] || null; }

function keyOfType(type) { return STRING_TYPES[type] ? (x => x) : (x => JSON.stringify(x)); }

function clearHold() {
 if(holdTimer) { clearTimeout(holdTimer); holdTimer = null; }
 holdTarget = null;
}

function beginDrag(item, handle, x, y) {
 const rect = item.getBoundingClientRect();
 const parent = item.parentNode;
 if(!parent) return;
 const placeholder = document.createElement('div');
 placeholder.className = 'drag-placeholder';
 placeholder.style.width = rect.width + 'px';
 placeholder.style.height = rect.height + 'px';
 const ghost = item.cloneNode(true);
 ghost.classList.add('drag-ghost');
 ghost.style.width = rect.width + 'px';
 ghost.style.height = rect.height + 'px';
 ghost.style.left = rect.left + 'px';
 ghost.style.top = rect.top + 'px';
 parent.insertBefore(placeholder, item);
 document.body.appendChild(ghost);
 item.style.display = 'none';
 dragState = { item, handle, placeholder, ghost, parent, offsetX: x - rect.left, offsetY: y - rect.top };
 Host.vibrate(30);
}

function updateDrag(x, y) {
 if(!dragState) return;
 const drag = dragState;
 drag.ghost.style.left = (x - drag.offsetX) + 'px';
 drag.ghost.style.top = (y - drag.offsetY) + 'px';
 const el = document.elementFromPoint(x, y);
 if(!el) return;
 const target = el.closest('.item');
 if(!target || target === drag.item || target === drag.placeholder || target.parentNode !== drag.parent) return;
 const rect = target.getBoundingClientRect();
 const refNode = x < rect.left + rect.width / 2 ? target : target.nextSibling;
 if(drag.placeholder !== refNode) drag.parent.insertBefore(drag.placeholder, refNode);
}

function reorderFromDOM(type, parentList) {
 const arr = arrForType(type);
 if(!arr) return;
 const items = parentList.querySelectorAll('.item');
 const keys = [];
 for (let i = 0; i < items.length; i++) {
  const handle = items[i].querySelector('.drag-handle');
  if(!handle || handle.dataset.itemType !== type) continue;
  keys.push(handle.dataset.itemValue);
 }
 if(!keys.length) return;
 reorderByKey(arr, keys, keyOfType(type));
}

function endDrag(commit) {
 if(!dragState) return;
 const drag = dragState;
 drag.item.style.display = '';
 if(commit) {
  drag.parent.insertBefore(drag.item, drag.placeholder);
  const type = drag.handle.dataset.itemType;
  reorderFromDOM(type, drag.parent);
  const field = fieldForType(type);
  if(field) {
   Store.markDirty(field);
   Store.flush();
   if(!PERSIST_SET.has(field)) Store.saveHistory();
  }
 }
 if(drag.placeholder.parentNode) drag.placeholder.parentNode.removeChild(drag.placeholder);
 if(drag.ghost.parentNode) drag.ghost.parentNode.removeChild(drag.ghost);
 dragState = null;
 suppressClickUntil = Date.now() + 300;
}

