 const handle = e.target.closest('.drag-handle');
 if(!handle) return;
 const item = handle.closest('.item');
 if(!item) return;
 holdStartX = e.clientX;
 holdStartY = e.clientY;
 holdTarget = { handle, item, x: e.clientX, y: e.clientY };
 holdTimer = setTimeout(() => {
  const pending = holdTarget;
  holdTarget = null;
  holdTimer = null;
  if(pending) beginDrag(pending.item, pending.handle, pending.x, pending.y);
 }, DRAG_HOLD_MS);
});

document.addEventListener('pointermove', e => {
 if(dragState) {
  if(e.cancelable) e.preventDefault();
  updateDrag(e.clientX, e.clientY);
  return;
 }
 if(holdTimer && holdTarget) {
  if(Math.abs(e.clientX - holdStartX) > DRAG_SLOP ||
   Math.abs(e.clientY - holdStartY) > DRAG_SLOP) {
   clearHold();
  }
 }
}, { passive: false });

document.addEventListener('pointerup', e => {
 if(dragState) { if(e.cancelable) e.preventDefault(); endDrag(true); return; }
 clearHold();
});

document.addEventListener('pointercancel', () => {
 if(dragState) endDrag(false);
 clearHold();
});

