/* =====  导入历史 ===== */
let histMask = null;

function histDialog(open) {
 if(!histMask) {
  histMask = document.createElement('div');
  histMask.className = 'hist-io-mask';
  histMask.innerHTML = '<div class="hist-io"><div class="hist-io-head"><h3 class="hist-io-title">导入历史</h3><button type="button" class="hist-io-x">×</button></div><div class="hist-io-body"><textarea class="hist-io-text" placeholder="请在此处粘贴历史记录..."></textarea><button type="button" class="hist-io-btn">导入</button></div></div>';
  histMask.addEventListener('click', e => {
   if(e.target === histMask || e.target.closest('.hist-io-x')) return histDialog(false);
   if(e.target.closest('.hist-io-btn')) histImport(histMask.querySelector('.hist-io-text').value);
  });
  document.body.appendChild(histMask);
 }
 if(open) {
  const ta = histMask.querySelector('.hist-io-text');
  ta.value = '';
  histMask.classList.add('open');
  setTimeout(() => ta.focus(), 50);
 } else {
  histMask.classList.remove('open');
 }
}

function histImport(text) {
 let d;
 try { d = JSON.parse(String(text || '').trim()); } catch (e) { return Host.toast('JSON 格式错误'); }
 if(!Array.isArray(d)) return Host.toast('数据格式错误');
 Store.reloadHistory();
 const cur = Store.state.history || [], seen = new Set(cur.map(x => x.url)), merged = cur.slice(); 
 let n = 0;
 d.forEach(x => {
  if(!x || !x.url || seen.has(x.url)) return;
  seen.add(x.url);
  merged.push({ title: String(x.title || x.url).trim(), url: String(x.url).trim(), time: Number(x.time) || 0, ...(x.collectionId ? { collectionId: String(x.collectionId) } : 0), ...(x.collectionName ? { collectionName: String(x.collectionName) } : 0) }); 
  n++;
 });
 if(!n) { histDialog(false); return Host.toast('无新增记录'); }
 merged.sort((a, b) => (+b.time || 0) - (+a.time || 0));
 if(merged.length > 500) merged.length = 500;
 Store.mutate('history', () => merged, { render: false });
 Store.saveHistory();
 invalidateSection('history');
 render();
 histDialog(false);
 Host.toast(`已导入 ${n} 条`);
}

